// Mã sản phẩm đôi khi lệch hoa/thường hoặc dư khoảng trắng giữa tab "Ảnh sản phẩm"
// và các tab giá (Kính/Ngói/Keo) -> chuẩn hóa để so khớp không bị bỏ lỡ ảnh.
function normMa(s){ return String(s||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,''); }
// Nhập số thập phân kiểu Việt Nam - bàn phím số điện thoại VN hay cho gõ dấu
// PHẨY (,) làm dấu thập phân, nhưng parseFloat() chỉ hiểu dấu CHẤM (.) - hàm
// này chấp nhận cả 2 kiểu để khách/nhân viên gõ 25,5 hay 25.5 đều ra đúng 25.5.
function parseVN(s){ return parseFloat(String(s||'').trim().replace(',','.'))||0; }
// Ảnh trong imgStore/imgStoreMulti giờ lưu theo Mã Sap (cột A, sheet mô tả/video)
// - nhiều dòng cùng Mã Sap được gộp thành 1 mảng ảnh ở server (Images.gs).
// Mỗi mã sản phẩm (ma) tra ra Mã Sap qua maToSap rồi mới tìm ảnh, để khớp đúng
// dù mã sản phẩm nằm ở cột nào trong sheet.
function timAnh(ma){
  var sap=maToSap[ma]||ma;
  if(imgStore[sap]) return imgStore[sap];
  if(imgStore[ma]) return imgStore[ma];
  var nm=normMa(ma);
  var k=Object.keys(imgStore).find(function(key){ return normMa(key)===nm; });
  return k?imgStore[k]:null;
}
function timAnhMulti(ma){
  var sap=maToSap[ma]||ma;
  if(imgStoreMulti[sap] && imgStoreMulti[sap].length) return imgStoreMulti[sap];
  if(imgStoreMulti[ma] && imgStoreMulti[ma].length) return imgStoreMulti[ma];
  var nm=normMa(ma);
  var k=Object.keys(imgStoreMulti).find(function(key){ return normMa(key)===nm; });
  if(k && imgStoreMulti[k] && imgStoreMulti[k].length) return imgStoreMulti[k];
  var single=timAnh(ma);
  return single?[single]:[];
}

// Tự động lướt qua các ảnh của 1 sản phẩm (mỗi 4s) ngay trên card danh sách,
// CHỈ chạy khi card đang thực sự hiện trong khung nhìn (viewport) - dùng
// IntersectionObserver dùng chung 1 lần cho mọi card, tránh mỗi card tự chạy
// 1 timer gây tốn tài nguyên khi cuộn qua danh sách dài (nhiều trang/nhiều card).
var _autoCycleObserver=null;
var _autoCycleTimers=(typeof WeakMap!=='undefined')?new WeakMap():null;
function _ensureAutoCycleObserver(){
  if(_autoCycleObserver) return _autoCycleObserver;
  _autoCycleObserver=new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      var el=entry.target;
      if(entry.isIntersecting){
        if(_autoCycleTimers.has(el)) return;
        var ma=el.dataset.autoCycleMa;
        var imgs=timAnhMulti(ma).map(convertImgUrl);
        if(imgs.length<2) return;
        var idx=0;
        var img=el.querySelector('img');
        if(!img) return;
        var timer=setInterval(function(){
          idx=(idx+1)%imgs.length;
          img.src=imgs[idx];
        },4000);
        _autoCycleTimers.set(el,timer);
      } else {
        var t=_autoCycleTimers.get(el);
        if(t){ clearInterval(t); _autoCycleTimers.delete(el); }
      }
    });
  },{threshold:0.2});
  return _autoCycleObserver;
}
function registerAutoCycle(thumbEl, ma){
  if(!thumbEl || !ma || !_autoCycleTimers || typeof IntersectionObserver==='undefined') return;
  var multi=timAnhMulti(ma);
  if(multi.length<2) return;
  thumbEl.dataset.autoCycleMa=ma;
  _ensureAutoCycleObserver().observe(thumbEl);
}

// Fetch bảng giá từ Google Sheet (JSONP)
// Gọi khi app mở — cập nhật DATA từ Sheet, không cần sửa code
// Áp giá gạch từ kết quả action=getGia(loai=gach) HOẶC phần "gach" của
// action=getAll vào mảng DATA - tách riêng để dùng chung cho cả 2 đường gọi.
function applyGiaGach(res){
  if(!res||!res.data||!res.data.length) return;
  var rows = res.data;
  rows.forEach(function(row){
    var ma = String(row.ma||'').trim();
    if(!ma) return;
    function pg(v){return parseFloat(String(v||'0').replace(/\./g,'').replace(/,/g,'.'))||0;}
    var le=pg(row.le), nhan=pg(row.nhan), giao=pg(row.giao);
    var nsSheet=pg(row.ns), nsCT1=pg(row.ns_ct1);
    // CT150 đã kết thúc - KHÔNG còn tự bịa giá Sale = nhận kho × 0.95 khi
    // không có dữ liệu Sale thật. Chỉ hiện "GIÁ SALE" khi Sheet có giá thật.
    var ns = nsSheet>0 ? nsSheet : (nsCT1>0 ? Math.round(nsCT1*0.95) : 0);
    var gs = pg(row.gs)||giao;

    // Tìm trong DATA hiện tại
    var p = DATA.find(function(x){return x.ma===ma;});
    if(p){
      // Mã đã có → chỉ cập nhật nếu giá > 0 (tránh ghi đè bằng 0 khi Sheet lỗi)
      if(le>0)   p.le=le;
      if(nhan>0) p.nhan=nhan;
      if(giao>0) p.giao=giao;
      if(ns>0)   p.ns=ns;
      if(gs>0)   p.gs=gs;
      if(row.sap) p.sap=String(row.sap).trim();
      // Tên hóa đơn (dùng khi xuất PDF/Excel để khớp đúng tên trên hóa đơn VAT)
      if(row.tenHD) p.tenHD=String(row.tenHD).trim();
    } else {
      // Mã MỚI trong Sheet → thêm vào DATA
      DATA.push({
        ma:ma, sap:String(row.sap||'').trim(), kc:String(row.kc||'').trim().replace(/X/g,'x'), cat:String(row.cat||'').toLowerCase(),
        gio:String(row.gio||''), ten:String(row.ten||ma),
        tenHD:String(row.tenHD||'').trim(),
        le:le, nhan:nhan, giao:giao, ns:ns, gs:gs
      });
    }
  });
  console.log('✅ Cập nhật giá gạch từ Sheet: '+rows.length+' mã (bao gồm mã mới)');
}

// Gọi 1 lần duy nhất (action=getAll) thay vì 5 lần riêng (giá gạch, ảnh,
// thuộc tính SP, CT1, CT2) khi mở app - mỗi lần gọi Apps Script rời rạc có
// phí khởi động ~2-5s không đổi được dù code nhanh hay chậm, gộp lại giúp
// chỉ tốn phí đó 1 lần. Nếu API gộp lỗi, tự động rơi về gọi riêng lẻ như cũ.
// Giãn cách các lệnh gọi Apps Script thay vì bắn đồng thời - Google chặn
// bớt (503) khi có quá nhiều request cùng lúc tới cùng 1 URL deploy, dù
// script chạy xong bình thường phía server (thấy rõ qua "Nhật ký thực thi"
// vẫn "Đã hoàn thành" trong khi trình duyệt nhận 503).
function goiTuanTu(fns, khoangCach){
  fns.forEach(function(fn, i){ setTimeout(fn, i*(khoangCach||280)); });
}

// Mở thẳng popup sản phẩm khi link có dạng ...?ma=<mã_sp> (chia sẻ link trực tiếp).
// Chỉ chạy 1 lần/phiên tải trang, sau khi DATA đã có dữ liệu (gọi trong _onGetAll).
var _deepLinkDone = false;
function tryOpenDeepLink(){
  if(_deepLinkDone) return;
  try{
    var ma = new URLSearchParams(location.search).get('ma');
    if(!ma || typeof DATA==='undefined') return;
    var p = DATA.find(function(x){ return x.ma===ma; });
    if(p){
      _deepLinkDone = true;
      setTimeout(function(){ showDP(ma); }, 50);
    }
  }catch(e){}
}
// Deep-link cho Ngói/Keo: mã SAP của 2 ngành hàng này chỉ có sau khi
// fetchGiaFromSheet(['ngoi','keo','kinh']) tải xong (Gạch dùng getAll riêng,
// xử lý ở tryOpenDeepLink() phía trên) - gọi hàm này sau khi NGOI/KEO đã đầy đủ.
function tryOpenDeepLinkNgoiKeo(){
  if(_deepLinkDone) return;
  try{
    var ma = new URLSearchParams(location.search).get('ma');
    if(!ma) return;
    var pN = (typeof NGOI!=='undefined') && NGOI.find(function(x){ return x.ma===ma; });
    if(pN){
      _deepLinkDone = true;
      setTimeout(function(){ swTab('ngoi'); showNgoi(ma); }, 50);
      return;
    }
    var pK = (typeof KEO!=='undefined') && KEO.find(function(x){ return x.ma===ma; });
    if(pK){
      _deepLinkDone = true;
      setTimeout(function(){ swTab('keo'); showKeo(ma); }, 50);
    }
  }catch(e){}
}

function fetchAllFromSheet(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  var old=document.getElementById('_all_script');
  if(old) old.remove();
  window._onGetAll = function(res){
    var s=document.getElementById('_all_script');
    if(s) s.remove();
    if(!res || res.status!=='ok'){
      console.log('⚠️ getAll lỗi, rơi về gọi riêng lẻ:', res && res.msg);
      goiTuanTu([
        function(){ fetchGiaFromSheet(['gach']); },
        function(){ fetchImagesFromSheet(); },
        function(){ fetchSpExtra(); },
        function(){ fetchThuocTinhSP(); },
        function(){ fetchCT('ct1'); },
        function(){ fetchCT('ct2'); }
      ]);
      return;
    }
    try{ applyGiaGach(res.gach); _syncFlags.gach=true; }catch(e){ console.log('Lỗi áp giá gạch (getAll):', e); }
    tryOpenDeepLink();
    try{ applyImagesData(res.images); }catch(e){ console.log('Lỗi áp ảnh (getAll):', e); }
    try{
      if(res.extra){ applySpExtraData(res.extra, res.maToSap, res.spImages, res.spImagesMulti); }
      else { fetchSpExtra(); }
    }catch(e){ fetchSpExtra(); }
    try{ applyThuocTinhData(res.thuocTinh); }catch(e){ console.log('Lỗi áp thuộc tính SP (getAll):', e); }
    try{ applyCTResult('ct1', res.ct1); }catch(e){ console.log('Lỗi áp CT1 (getAll):', e); }
    try{ applyCTResult('ct2', res.ct2); }catch(e){ console.log('Lỗi áp CT2 (getAll):', e); }
    try{ applyCTMuaTangXaKho(res.ctMuaTang, res.ctXaKho); }catch(e){ console.log('Lỗi áp CT Mua Tặng/Xả Kho (getAll):', e); }
    // Ngói/Keo/Kính + Trọng lượng giờ đi kèm getAll (trước đây 2 request rời,
    // mỗi request tốn ~4-7s phí khởi động Apps Script) - chỉ gọi rời khi
    // getAll không kèm theo (lỗi/cache cũ) để không mất tính năng.
    try{
      if(res.ngoiKeoKinh && res.ngoiKeoKinh.status==='ok'){
        _apDungGiaLoai('ngoi', res.ngoiKeoKinh.ngoi);
        _apDungGiaLoai('keo',  res.ngoiKeoKinh.keo);
        _apDungGiaLoai('kinh', res.ngoiKeoKinh.kinh);
        _hoanTatDongBoGia();
      } else {
        fetchNgoiKeoKinhCombined();
      }
    }catch(e){ fetchNgoiKeoKinhCombined(); }
    try{
      if(res.trongLuong && res.trongLuong.status==='ok' && res.trongLuong.data){ trongLuongMap=res.trongLuong.data; }
      else { fetchTrongLuong(); }
    }catch(e){ fetchTrongLuong(); }
  };
  var s=document.createElement('script');
  s.id='_all_script';
  var _tok=authTok();
  s.src=APPS_URL+'?action=getAll&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(_tok)+(_tok?'':'&g=1')+'&callback=_onGetAll';
  s.onerror=function(){
    console.log('⚠️ Không tải được dữ liệu gộp — rơi về gọi riêng lẻ');
    s.remove();
    goiTuanTu([
      function(){ fetchGiaFromSheet(['gach']); },
      function(){ fetchImagesFromSheet(); },
      function(){ fetchSpExtra(); },
      function(){ fetchThuocTinhSP(); },
      function(){ fetchCT('ct1'); },
      function(){ fetchCT('ct2'); }
    ]);
  };
  document.head.appendChild(s);
  // Ngói/Keo/Kính giờ đi kèm trong response getAll (res.ngoiKeoKinh) — xem
  // xử lý trong _onGetAll ở trên; chỉ gọi rời khi getAll không trả kèm.
}

// Áp dữ liệu giá của 1 nhóm (gach/ngoi/keo/kinh) vào biến toàn cục tương ứng.
// Dùng chung cho cả đường gọi rời (fetchGiaFromSheet) lẫn đường gộp
// (fetchNgoiKeoKinhCombined) để không lặp lại logic 2 nơi.
function _apDungGiaLoai(loai, res){
  if(!res||!res.data||!res.data.length) return;
  var rows = res.data;

  if(loai==='gach'){
    applyGiaGach(res);
  }
  else if(loai==='ngoi'){
          function pg2(v){return parseFloat(String(v||'0').replace(/\./g,'').replace(/,/g,'.'))||0;}
          // Cấu trúc MỚI: mã = Mã SAP, tên chứa mã màu (Ngói lợp TITAN003...)
          var newRows = rows.filter(function(r){ return /(TITAN|ALPHA)\s?0*\d/i.test(String(r.ten||'')); });
          if(newRows.length>20){
            NGOI.length=0;
            newRows.forEach(function(row){
              NGOI.push({
                ma:String(row.ma||'').trim(), ten:String(row.ten||'').trim(),
                tenHD:String(row.tenHD||'').trim(),
                kc:String(row.kc||''), dong_goi:String(row.dong_goi||'6v/thùng'),
                unit:'vien', cat:'ngoi', _new:true,
                le:pg2(row.le), nhan:pg2(row.nhan), nhan2:pg2(row.nhan2),
                giao:pg2(row.giao), giao2:pg2(row.giao2), ns:0, gs:0
              });
            });
            var tabNgoi=document.getElementById('tab-ngoi');
            if(tabNgoi && tabNgoi.classList.contains('on')) renderNgoi();
            console.log('✅ Ngói (cấu trúc mới): '+NGOI.length+' mã theo màu');
          } else {
            // Cấu trúc CŨ: merge theo mã như trước
            rows.forEach(function(row){
              var ma = String(row.ma||'').trim();
              var p = NGOI.find(function(x){return x.ma===ma;});
              if(p){
                var _le=pg2(row.le),_nhan=pg2(row.nhan),_nhan2=pg2(row.nhan2);
                var _giao=pg2(row.giao),_giao2=pg2(row.giao2);
                // Guard > 0: không ghi đè nếu Sheet trả về 0
                if(_le>0)    p.le=_le;
                if(_nhan>0)  p.nhan=_nhan;
                if(_nhan2>0) p.nhan2=_nhan2;
                if(_giao>0)  p.giao=_giao;
                if(_giao2>0) p.giao2=_giao2;
                var nsNgoi = pg2(row.ns);
                p.ns = nsNgoi > 0 ? nsNgoi : Math.round(p.nhan * 0.90);
                p.gs = pg2(row.gs) || p.giao;
              }
            });
            console.log('✅ Cập nhật giá ngói từ Sheet: '+rows.length+' mã');
          }
        }
        else if(loai==='keo'){
          function pgKeo(v){return parseFloat(String(v||"0").replace(/\./g,"").replace(/,/g,"."))||0;}
          // Cấu trúc MỚI: mã = Mã SAP (số dài)
          var newK = rows.filter(function(r){ return /^\d{6,}$/.test(String(r.ma||'').trim()); });
          if(newK.length>3){
            KEO.length=0;
            newK.forEach(function(row){
              KEO.push({
                ma:String(row.ma||'').trim(), ten:String(row.ten||'').trim(),
                tenHD:String(row.tenHD||'').trim(),
                kc:String(row.qc||row.kc||''), dv:String(row.dv||'bao'),
                unit:'bao', cat:'keo', _new:true,
                le:pgKeo(row.le), nhan:pgKeo(row.nhan), nhan2:pgKeo(row.nhan2),
                giao:pgKeo(row.giao), giao2:pgKeo(row.giao2), ns:0, gs:0
              });
            });
            var tabKeo=document.getElementById('tab-keo');
            if(tabKeo && tabKeo.classList.contains('on')) renderKeo();
            console.log('✅ Keo/bột chà ron (cấu trúc mới): '+KEO.length+' mã');
          } else {
            rows.forEach(function(row){
              var ma = String(row.ma||'').trim();
              var p = KEO.find(function(x){return x.ma===ma;});
              if(p){
                var _le=pgKeo(row.le),_nhan=pgKeo(row.nhan),_nhan2=pgKeo(row.nhan2);
                var _giao=pgKeo(row.giao),_giao2=pgKeo(row.giao2);
                if(_le>0)    p.le=_le;
                if(_nhan>0)  p.nhan=_nhan;
                if(_nhan2>0) p.nhan2=_nhan2;
                if(_giao>0)  p.giao=_giao;
                if(_giao2>0) p.giao2=_giao2;
              }
            });
            console.log('✅ Cập nhật giá keo từ Sheet: '+rows.length+' mã');
          }
        }
        else if(loai==='kinh'){
          function pgK(v){return parseFloat(String(v||"0").replace(/\./g,"").replace(/,/g,"."))||0;}
          // Cấu trúc MỚI: mã = Mã SAP (số dài)
          var newK = rows.filter(function(r){ return /^\d{6,}$/.test(String(r.ma||'').trim()); });
          if(newK.length>=1){
            KINH.length=0;
            newK.forEach(function(row){
              KINH.push({
                ma:String(row.ma||'').trim(), ten:String(row.ten||'').trim(),
                tenHD:String(row.tenHD||'').trim(),
                kc:String(row.kc||''), dong_goi:String(row.dong_goi||'6v/thùng'),
                unit:'thùng', cat:'kinh', loai:'kinh', _new:true,
                le:pgK(row.le), nhan:pgK(row.nhan), nhan2:pgK(row.nhan2), nhan3:pgK(row.nhan3),
                giao:pgK(row.giao), giao2:pgK(row.giao2), giao3:pgK(row.giao3),
                ns:0, gs:0
              });
            });
            console.log('✅ Kính (cấu trúc mới): '+KINH.length+' mã');
          } else {
            rows.forEach(function(row){
              var ma = String(row.ma||'').trim();
              var p = KINH.find(function(x){return x.ma===ma;});
              if(p){
                var _le=pgK(row.le),_nhan=pgK(row.nhan),_nhan2=pgK(row.nhan2),_nhan3=pgK(row.nhan3);
                var _giao=pgK(row.giao),_giao2=pgK(row.giao2),_giao3=pgK(row.giao3);
                if(_le>0)    p.le=_le;
                if(_nhan>0)  p.nhan=_nhan;
                if(_nhan2>0) p.nhan2=_nhan2;
                if(_nhan3>0) p.nhan3=_nhan3;
                if(_giao>0)  p.giao=_giao;
                if(_giao2>0) p.giao2=_giao2;
                if(_giao3>0) p.giao3=_giao3;
              }
            });
            console.log('✅ Cập nhật giá kính từ Sheet: '+rows.length+' mã');
          }
  }

  _syncFlags[loai]=true;
}

function _hoanTatDongBoGia(){
  var badge = document.getElementById('gia-source-badge');
  if(badge){
    badge.textContent = '✅';
    badge.style.background = '#E8F5E9';
    badge.style.color = '#1B5E20';
  }
  render();
  renderSale();
  tryOpenDeepLinkNgoiKeo();
  console.log('🎉 Đã đồng bộ giá từ Sheet xong!');
}

// Ngói+Keo+Kính gộp thành 1 request duy nhất (action=getGiaNgoiKeoKinh) -
// nhanh hơn hẳn so với bắn 3 request rời, mỗi request tốn thời gian khởi
// động riêng của Apps Script (đặc biệt rõ khi F5/đăng nhập lại).
function fetchNgoiKeoKinhCombined(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  window._onGiaNgoiKeoKinh=function(res){
    try{
      if(res && res.status==='ok'){
        _apDungGiaLoai('ngoi', res.ngoi);
        _apDungGiaLoai('keo',  res.keo);
        _apDungGiaLoai('kinh', res.kinh);
        _hoanTatDongBoGia();
      }
    }catch(e){ console.log('Lỗi parse giá Ngói/Keo/Kính (gộp):', e.message); }
    var s=document.getElementById('_gia_nkk_script');
    if(s) s.remove();
  };
  var old=document.getElementById('_gia_nkk_script');
  if(old) old.remove();
  var s=document.createElement('script');
  s.id='_gia_nkk_script';
  var _tok=authTok();
  s.src=APPS_URL+'?action=getGiaNgoiKeoKinh&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(_tok)+(_tok?'':'&g=1')+'&callback=_onGiaNgoiKeoKinh';
  s.onerror=function(){
    console.log('⚠️ Không tải được giá Ngói/Keo/Kính gộp — rơi về gọi riêng lẻ');
    s.remove();
    fetchGiaFromSheet(['ngoi','keo','kinh']);
  };
  document.head.appendChild(s);
}

// Đường gọi rời từng loại (dự phòng khi getGiaNgoiKeoKinh lỗi, và vẫn dùng
// cho 'gach' trong nhánh fallback goiTuanTu khi getAll thất bại).
function fetchGiaFromSheet(loaisOverride){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  var loais = loaisOverride || ['gach','ngoi','keo','kinh'];
  var loaded = 0;

  loais.forEach(function(loai, _idx){
    window['_onGia_'+loai] = function(res){
      try{
        _apDungGiaLoai(loai, res);
        loaded++;
        if(loaded===loais.length) _hoanTatDongBoGia();
      }catch(e){ console.log('Lỗi parse giá '+loai+':', e.message); }
      var s=document.getElementById('_gia_script_'+loai);
      if(s) s.remove();
    };

    var old=document.getElementById('_gia_script_'+loai);
    if(old) old.remove();
    // Giãn cách khi loais có nhiều phần tử để không bắn nhiều request cùng
    // lúc tới cùng 1 URL (xem goiTuanTu ở trên).
    setTimeout(function(){
      var s=document.createElement('script');
      s.id='_gia_script_'+loai;
      // g=1: khách lẻ (không token) → server chỉ trả giá lẻ, giấu giá ĐL/sale
      var _tok=authTok();
      s.src=APPS_URL+'?action=getGia&loai='+loai+'&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(_tok)+(_tok?'':'&g=1')+'&callback=_onGia_'+loai;
      s.onerror=function(){
        console.log('⚠️ Không tải được giá '+loai+' từ Sheet — dùng giá trong app');
        s.remove();
      };
      document.head.appendChild(s);
    }, _idx*280);
  });
}


// Fetch ảnh từ Google Sheet khi đăng nhập (dùng script tag để tránh CORS)
// Áp dữ liệu ảnh (từ action=getImages hoặc phần "images" của getAll) vào
// imgStore/imgStoreMulti - tách riêng để dùng chung cho cả 2 đường gọi.
// Chỉ chấp nhận giá trị trông giống URL ảnh thật (http/https) - chặn trường hợp
// Sheet bị gõ nhầm/lệch cột khiến cột ảnh chứa chữ (vd tên sản phẩm) thay vì link.
function _isValidImgUrl(u){ return typeof u==='string' && /^https?:\/\//i.test(u); }
function applyImagesData(data){
  try{
    if(data && data.images){
      var map=data.images, count=0;
      var validMap={};
      Object.keys(map).forEach(function(ma){
        // Đổi link chia sẻ Drive (.../view?usp=...) sang dạng ảnh nhúng được
        // (lh3.googleusercontent.com) NGAY LÚC LƯU - card ngoài danh sách chèn
        // thẳng imgStore vào <img src> không tự đổi link như popup chi tiết,
        // nếu để nguyên link chia sẻ thì ảnh sẽ không tải được (hiện "Chưa có ảnh").
        if(_isValidImgUrl(map[ma])){ validMap[ma]=convertImgUrl(map[ma]); count++; }
      });
      // Thay hẳn theo dữ liệu mới nhất (không chỉ merge thêm) - mã nào đã bị xoá/sửa
      // sai ở Sheet thì cũng bị xoá khỏi cache, tránh ảnh cũ/sai kẹt lại vĩnh viễn
      // trong localStorage dù Sheet đã được sửa đúng.
      Object.keys(imgStore).forEach(function(ma){ if(!(ma in validMap)) delete imgStore[ma]; });
      Object.keys(validMap).forEach(function(ma){ imgStore[ma]=validMap[ma]; });
      // Build multi: data.imagesMulti[ma] = [url1,url2,...]
      if(data.imagesMulti){
        var validMulti={};
        Object.keys(data.imagesMulti).forEach(function(ma){
          var list=(data.imagesMulti[ma]||[]).filter(_isValidImgUrl).map(convertImgUrl);
          if(list.length) validMulti[ma]=list;
        });
        Object.keys(imgStoreMulti).forEach(function(ma){ if(!(ma in validMulti)) delete imgStoreMulti[ma]; });
        Object.keys(validMulti).forEach(function(ma){ imgStoreMulti[ma]=validMulti[ma]; });
        try{ localStorage.setItem('dt_imgs_multi', JSON.stringify(imgStoreMulti)); }catch(e){}
      }
      try{ localStorage.setItem('dt_imgs', JSON.stringify(imgStore)); }catch(e){}
      if(curP_ma) loadImg(curP_ma);
      // Ảnh thường tải xong SAU khi lưới sản phẩm đã render lần đầu (dữ liệu ảnh
      // là request riêng, chậm hơn giá) - phải render lại lưới đang hiển thị (Tất cả/
      // Danh mục) chứ không chỉ renderSale(), nếu không card sẽ kẹt ở "Chưa có ảnh"
      // dù imgStore đã có đủ dữ liệu.
      if(typeof render==='function') render();
      renderSale(); // refresh ảnh trong sale grid
      console.log('✅ Đã tải '+count+' ảnh từ Sheet');
    }
  }catch(e){ console.log('Lỗi parse ảnh:', e); }
}

function fetchImagesFromSheet(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';

  // Dùng JSONP: inject script tag để bypass CORS
  window._onImgData = function(data){
    applyImagesData(data);
    // Xóa script tag sau khi xong
    var old=document.getElementById('_img_script');
    if(old) old.remove();
  };

  // Xóa script cũ nếu có
  var old=document.getElementById('_img_script');
  if(old) old.remove();

  var s=document.createElement('script');
  s.id='_img_script';
  s.src=APPS_URL+'?action=getImages&k='+encodeURIComponent(APP_KEY)+'&callback=_onImgData';
  s.onerror=function(){
    console.log('⚠️ Không kết nối được Sheet – dùng cache localStorage');
    s.remove();
  };
  document.head.appendChild(s);
}
function applySpExtraData(extra, sapMap, images, imagesMulti){
  if(!extra && !sapMap && !images && !imagesMulti) return;
  if(sapMap){
    Object.keys(sapMap).forEach(function(maApp){ maToSap[maApp]=sapMap[maApp]; });
  }
  if(extra){
    Object.keys(extra).forEach(function(sap){ spExtra[sap]=extra[sap]; });
    try{ localStorage.setItem('dt_spextra', JSON.stringify(spExtra)); }catch(e){}
    console.log('✅ Đã tải extra info '+Object.keys(extra).length+' SP (keyed by SAP)');
  }
  // Ảnh sản phẩm giờ lấy từ chính sheet mô tả/video (cột ảnh), không còn
  // phụ thuộc tab "Ảnh sản phẩm" riêng (đã bị xóa) - dùng chung applyImagesData
  // để merge vào imgStore/imgStoreMulti + ghi localStorage như luồng getImages cũ.
  if(images || imagesMulti){
    applyImagesData({images:images, imagesMulti:imagesMulti});
  }
}

function fetchSpExtra(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  window._onSpExtra=function(data){
    var old=document.getElementById('_spextra_script'); if(old) old.remove();
    applySpExtraData(data && data.extra, data && data.maToSap, data && data.images, data && data.imagesMulti);
  };
  var old=document.getElementById('_spextra_script'); if(old) old.remove();
  var s=document.createElement('script');
  s.id='_spextra_script';
  s.src=APPS_URL+'?action=getSpExtra&k='+encodeURIComponent(APP_KEY)+'&callback=_onSpExtra';
  s.onerror=function(){
    console.log('⚠️ Không tải được spExtra – fallback getImages');
    s.remove();
    fetchImagesFromSheet();
  };
  document.head.appendChild(s);
}

function escHtml(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

var _dpVidMa=null;
// Hàm dùng chung hiển thị Mô tả + Video sản phẩm cho MỌI ngành hàng
// (Gạch/Ngói/Keo) - mỗi popup truyền "prefix" riêng ứng với bộ id HTML
// của popup đó (vd 'dp' cho Gạch, 'nd' cho Ngói, 'kd' cho Keo).
// Nếu popup không có phần tab video riêng (chỉ Gạch có #dp-tbtn-video)
// thì bỏ qua bước ẩn/hiện tab, không lỗi gì.
var _extraVidMa={}; // ma hiện tại đang xem video, theo từng prefix (tránh đụng nhau giữa các popup)
function renderExtraGeneric(ma, prefix){
  var sap=maToSap[ma];
  var ex=sap?spExtra[sap]:null;
  var wrapEl=document.getElementById(prefix+'-extra-wrap');
  if(!ex){
    if(wrapEl) wrapEl.style.display='none';
    var vb=document.getElementById(prefix+'-tbtn-video'); if(vb) vb.style.display='none';
    var ivb=document.getElementById(prefix+'-img-video-badge'); if(ivb) ivb.style.display='none';
    return;
  }
  if(wrapEl) wrapEl.style.display='block';
  _extraVidMa[prefix]=ma;

  // Mô tả
  var motaSec=document.getElementById(prefix+'-mota-section');
  var hasMota=ex.mo_ta||ex.highlights;
  if(motaSec){
    if(hasMota){
      motaSec.style.display='block';
      var motaEl=document.getElementById(prefix+'-mota');
      if(motaEl) motaEl.innerHTML=(ex.mo_ta||'').split('\n').map(function(l){ return l?'<p>'+escHtml(l)+'</p>':''; }).join('');
      var hlEl=document.getElementById(prefix+'-highlights');
      if(hlEl){
        if(ex.highlights){
          var items=ex.highlights.split('\n').filter(Boolean);
          hlEl.innerHTML='<ul>'+items.map(function(i){return '<li>'+escHtml(i)+'</li>';}).join('')+'</ul>';
        } else { hlEl.innerHTML=''; }
      }
    } else { motaSec.style.display='none'; }
  }

  // Video
  var vidSec=document.getElementById(prefix+'-video-section');
  var hasVid=ex.tiktok||ex.youtube;
  var vidTabBtn=document.getElementById(prefix+'-tbtn-video');
  if(vidTabBtn) vidTabBtn.style.display=hasVid?'':'none';
  // Nhãn "Xem video" nổi trên ảnh sản phẩm (hiện tại chỉ popup Gạch có, id
  // dp-img-video-badge) - báo ngay có video mà không cần dò tab riêng.
  var imgVidBadge=document.getElementById(prefix+'-img-video-badge');
  if(imgVidBadge) imgVidBadge.style.display=hasVid?'flex':'none';
  if(vidSec){
    if(hasVid){
      vidSec.style.display='block';
      var tabsEl=document.getElementById(prefix+'-video-tabs');
      var embedEl=document.getElementById(prefix+'-video-embed');
      if(embedEl) embedEl.innerHTML=''; // clear cũ
      if(ex.tiktok&&ex.youtube){
        tabsEl.innerHTML='<button class="dp-vid-tab active" onclick="extraShowVideo(\''+prefix+'\',\'tiktok\')">▶ TikTok</button>'
                        +'<button class="dp-vid-tab" onclick="extraShowVideo(\''+prefix+'\',\'youtube\')">▶ YouTube</button>';
        tabsEl.style.display='flex';
      } else { tabsEl.innerHTML=''; tabsEl.style.display='none'; }
      extraShowVideo(prefix, ex.tiktok?'tiktok':'youtube');
    } else { vidSec.style.display='none'; }
  }
}

function extraShowVideo(prefix, type){
  var ma=_extraVidMa[prefix];
  var sap=maToSap[ma];
  var ex=sap?spExtra[sap]:null; if(!ex) return;
  var embedEl=document.getElementById(prefix+'-video-embed'); if(!embedEl) return;
  var tabsEl=document.getElementById(prefix+'-video-tabs');
  if(tabsEl) Array.prototype.forEach.call(tabsEl.querySelectorAll('.dp-vid-tab'), function(b){
    b.classList.toggle('active', b.textContent.toLowerCase().indexOf(type)>=0);
  });
  var url=type==='tiktok'?ex.tiktok:ex.youtube;
  embedEl.style.aspectRatio=type==='tiktok'?'9/16':'16/9';
  embedEl.innerHTML=buildVideoIframeHtml(type,url);
}

// Tạo HTML iframe embed cho TikTok/YouTube từ URL gốc - dùng chung cho mọi nơi
// hiển thị video (popup Gạch/Ngói/Keo và card Kính).
function buildVideoIframeHtml(type,url){
  var iframeUrl='';
  if(type==='tiktok'){
    var m=url.match(/\/video\/(\d+)/);
    iframeUrl=m?'https://www.tiktok.com/embed/v2/'+m[1]+'?lang=vi-VN':url;
  } else {
    var ym=url.match(/(?:youtu\.be\/|[?&]v=|\/shorts\/)([A-Za-z0-9_-]{11})/);
    iframeUrl=ym?'https://www.youtube.com/embed/'+ym[1]:url;
  }
  return '<iframe src="'+iframeUrl+'" style="width:100%;height:100%;border:none" allow="autoplay;encrypted-media" allowfullscreen loading="lazy"></iframe>';
}

// Giữ tên hàm cũ (dùng ở nhiều nơi khác) để không phải sửa các chỗ gọi cũ
function renderDpExtra(ma){ renderExtraGeneric(ma, 'dp'); }
function dpShowVideo(type){ extraShowVideo('dp', type); }

function copyMotaZalo(){
  var sap=maToSap[curP_ma];
  var ex=sap?spExtra[sap]:null;
  var lines=[];
  if(ex){
    if(ex.mo_ta) lines.push(ex.mo_ta);
    if(ex.highlights) lines.push(ex.highlights);
  }
  var msg=lines.join('\n\n');
  if(!msg){ showToast('⚠️ Chưa có mô tả cho sản phẩm này'); return; }
  navigator.clipboard&&navigator.clipboard.writeText
    ?navigator.clipboard.writeText(msg).then(function(){showToast('✅ Đã copy mô tả!');}).catch(function(){fallbackCopy(msg);})
    :fallbackCopy(msg);
}

function copyLinkSanPham(ma){
  if(!ma){ showToast('⚠️ Không xác định được mã sản phẩm'); return; }
  var url = location.origin + location.pathname + '?ma=' + encodeURIComponent(ma);
  navigator.clipboard&&navigator.clipboard.writeText
    ?navigator.clipboard.writeText(url).then(function(){showToast('✅ Đã copy link sản phẩm!');}).catch(function(){fallbackCopy(url);})
    :fallbackCopy(url);
}

function chiaSeVideoSanPham(ma){
  var p=DATA.find(function(x){return x.ma===ma;}); if(!p) return;
  var sap=maToSap[ma];
  var ex=sap?spExtra[sap]:null;
  if(!ex||(!ex.tiktok&&!ex.youtube)){ showToast('⚠️ Sản phẩm này chưa có video'); return; }
  var ten=p.ten||p.tenHD||ma;
  var lines=['🎥 *Video tham khảo sản phẩm:*','*'+ten+'*','Mã: '+ma];
  if(ex.tiktok)   lines.push('▶ TikTok: '+ex.tiktok);
  if(ex.youtube)  lines.push('▶ YouTube: '+ex.youtube);
  lines.push('','📍 Đồng Tâm KV23 – Lê Chí Linh');
  var msg=lines.join('\n');
  var firstUrl=ex.tiktok||ex.youtube;
  // Mobile: dùng Web Share API để mở sheet Zalo
  if(navigator.share){
    navigator.share({text:msg,url:firstUrl}).catch(function(e){
      if(e&&e.name==='AbortError') return;
      _copyVideoMsg(msg);
    });
  } else {
    _copyVideoMsg(msg);
  }
}
function _copyVideoMsg(msg){
  navigator.clipboard&&navigator.clipboard.writeText
    ?navigator.clipboard.writeText(msg).then(function(){showToast('✅ Đã copy lời nhắn video – dán vào Zalo!');}).catch(function(){fallbackCopy(msg);})
    :fallbackCopy(msg);
}

function setSize(sz){
  curSize=sz;
  document.querySelectorAll('.sz-item').forEach(function(el){el.classList.remove('on');});
  var map={'all':'sz-all','600x1200':'sz-60x120','1000x1000':'sz-100x100','800x800':'sz-80x80','600x600':'sz-60x60','400x800':'sz-40x80','300x600':'sz-30x60','400x400':'sz-40x40','300x300':'sz-30x30','200x800':'sz-20x80','200x1200':'sz-20x120','200x200':'sz-20x20','150x300':'sz-15x30','250x600':'sz-25x60','100x200':'sz-10x20'};
  var el=document.getElementById(map[sz]||'sz-all'); if(el) el.classList.add('on');
  curPage=0;
  // Nếu đang ở tab Sale thì render Sale theo kích thước
  if(curF==='sale') renderSale();
  else render();
}

