// Danh sách nut bottom-nav hien tai (6 nut): danhmuc/tra/ngoi/keo/tbvs/son.
// Sale, Kinh, Don khong con nam trong bottom-nav (Sale = chip trong tab Gach,
// Don = icon gio hang tren topbar) nhung tab-content cua chung van ton tai,
// van dieu huong toi duoc qua swTab() nhu cu.
var BOTTOM_NAV_TABS = ['danhmuc','tra','ngoi','keo','tbvs','son'];
function swTab(t){
  // Desktop: cart là panel cố định bên phải, không cần chuyển tab
  if(t==='don' && window.innerWidth>=768){
    renderDon();
    BOTTOM_NAV_TABS.forEach(function(x){
      var b=document.getElementById('bn-'+x); if(b) b.classList.toggle('on',false);
    });
    return;
  }
  ['tra','sale','ngoi','keo','kinh','don','danhmuc','tbvs','son','timkiem','video'].forEach(function(x){
    var el=document.getElementById('tab-'+x); if(el) el.classList.toggle('on',x===t);
  });
  BOTTOM_NAV_TABS.forEach(function(x){
    var b=document.getElementById('bn-'+x); if(b) b.classList.toggle('on',x===t);
  });
  ['timkiem','danhmuc','don','sale','video'].forEach(function(x){
    var b=document.getElementById('sn-'+x); if(b) b.classList.toggle('on',x===t);
  });
  document.querySelectorAll('.tb').forEach(function(b,i){
    b.classList.toggle('on',['tra','sale','ngoi','keo','kinh','don'][i]===t);
  });
  capNhatFilterSide();
  if(t==='sale')  { window._sf2=window._sf2||'ct1'; renderSale(); }
  if(t==='ngoi')  renderNgoi();
  if(t==='keo')   renderKeo();
  if(t==='kinh')  renderKinh();
  if(t==='don')   renderDon();
  if(t==='video') renderVideoGrid();
}

// ===== TAB VIDEO: lưới sản phẩm đang có video TikTok/YouTube =====
// Duyệt thẳng từ DATA (đã có "ma" - mã hiển thị/tên báo giá App đúng chuẩn)
// rồi tra spExtra qua maToSap[p.ma] - KHÔNG suy ngược từ maToSap vì object
// này có cả entry tự ánh xạ (maToSap[sap]=sap) chèn lẫn với entry thật
// (maToSap[ma]=sap), đảo ngược dễ bị entry tự ánh xạ ghi đè sai mã.
function danhSachSPCoVideo(){
  var list=[];
  (typeof DATA!=='undefined'?DATA:[]).forEach(function(p){
    var sap=maToSap[p.ma];
    var ex=sap?spExtra[sap]:null;
    if(!ex || (!ex.tiktok && !ex.youtube)) return;
    list.push({ma:p.ma, kc:p.kc, le:p.le, hasTiktok:!!ex.tiktok, hasYoutube:!!ex.youtube});
  });
  return list;
}
function renderVideoGrid(){
  var el=document.getElementById('video-grid');
  var emptyEl=document.getElementById('video-empty');
  if(!el) return;
  var list=danhSachSPCoVideo();
  if(!list.length){
    el.innerHTML='';
    if(emptyEl) emptyEl.style.display='block';
    return;
  }
  if(emptyEl) emptyEl.style.display='none';
  el.innerHTML=list.map(function(v){
    var imgUrl=timAnh(v.ma)||'';
    var giaHtml=v.le>0?'<div class="video-card-le">'+v.le.toLocaleString('vi-VN')+'đ/m²</div>':'';
    return '<div class="video-card" onclick="moVideoTuLuoi(\''+v.ma+'\')">'
      +'<div class="video-card-thumb">'
      +(imgUrl?'<img src="'+imgUrl+'" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">':'')
      +'<div class="video-card-play"><span>▶</span></div>'
      +'</div>'
      +'<div class="video-card-body">'
      +'<div class="video-card-ma">'+v.ma+'</div>'
      +giaHtml
      +'</div>'
      +'</div>';
  }).join('');
}
// Bấm vào 1 video trong lưới: Mobile mở feed cuộn dọc kiểu TikTok (đắm
// chìm hơn), Desktop vẫn mở popup chi tiết + nhảy tab Video như cũ (đã có
// sẵn khung 2 cột giá/video hiển thị song song, không cần feed riêng).
function moVideoTuLuoi(ma){
  if(window.innerWidth<768){ openVideoFeed(ma); return; }
  showDP(ma);
  setTimeout(function(){ dpSetTab('video'); },50);
}

// ===== VIDEO FEED (Mobile): cuộn dọc kiểu TikTok giữa các video sản phẩm =====
var _vfObserver=null;
function openVideoFeed(startMa){
  var list=danhSachSPCoVideo();
  if(!list.length) return;
  var scrollEl=document.getElementById('vf-scroll');
  scrollEl.innerHTML=list.map(function(v){
    var sap=maToSap[v.ma];
    var ex=sap?spExtra[sap]:null;
    var type=ex&&ex.tiktok?'tiktok':'youtube';
    var url=ex?(ex.tiktok||ex.youtube):'';
    var imgUrl=timAnh(v.ma)||'';
    var giaHtml=v.le>0?'<div class="vf-info-le">'+v.le.toLocaleString('vi-VN')+'đ/m²</div>':'';
    return '<div class="vf-slide" data-ma="'+v.ma+'" data-vtype="'+type+'" data-vurl="'+escHtml(url)+'">'
      +(imgUrl?'<div class="vf-slide-poster" style="background-image:url(\''+imgUrl+'\')"></div>':'')
      +'<div class="vf-slide-thumb">'
      +(imgUrl?'<img src="'+imgUrl+'" loading="lazy" decoding="async">':'')
      +'<div class="vf-play-btn">▶</div>'
      +'</div>'
      +'<div class="vf-info">'
      +'<div class="vf-info-ma">'+v.ma+'</div>'
      +(v.kc?'<div class="vf-info-kc">'+v.kc+'</div>':'')
      +giaHtml
      +'<button class="vf-info-btn" onclick="event.stopPropagation();xemChiTietTuVideoFeed(\''+v.ma+'\')">📋 Xem chi tiết sản phẩm</button>'
      +'</div>'
      +'</div>';
  }).join('');

  // Chỉ tạo iframe (autoplay) cho slide đang hiện rõ nhất trên màn hình -
  // vừa đỡ hao pin/băng thông khi có hàng chục video, vừa "pause" tự nhiên
  // video cũ khi cuộn qua (bỏ iframe = dừng phát).
  if(_vfObserver) _vfObserver.disconnect();
  _vfObserver=new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      var slide=en.target;
      if(en.isIntersecting && en.intersectionRatio>0.6){
        if(slide.querySelector('iframe')) return;
        var type=slide.dataset.vtype, url=slide.dataset.vurl;
        if(!url) return;
        var thumb=slide.querySelector('.vf-slide-thumb');
        if(thumb) thumb.outerHTML=buildVideoIframeHtml(type,url);
      } else {
        var ifr=slide.querySelector('iframe');
        if(ifr){
          var imgUrl=timAnh(slide.dataset.ma)||'';
          ifr.outerHTML='<div class="vf-slide-thumb">'
            +(imgUrl?'<img src="'+imgUrl+'" loading="lazy" decoding="async">':'')
            +'<div class="vf-play-btn">▶</div></div>';
        }
      }
    });
  },{root:scrollEl, threshold:[0,0.6]});
  scrollEl.querySelectorAll('.vf-slide').forEach(function(s){ _vfObserver.observe(s); });

  document.getElementById('video-feed').classList.add('on');
  document.body.style.overflow='hidden';
  var startSlide=scrollEl.querySelector('.vf-slide[data-ma="'+startMa+'"]');
  if(startSlide) startSlide.scrollIntoView({block:'start'});
}
function closeVideoFeed(){
  document.getElementById('video-feed').classList.remove('on');
  document.body.style.overflow='';
  if(_vfObserver){ _vfObserver.disconnect(); _vfObserver=null; }
  document.getElementById('vf-scroll').innerHTML=''; // dừng hết video đang phát
}
function xemChiTietTuVideoFeed(ma){
  closeVideoFeed();
  showDP(ma);
  setTimeout(function(){ dpSetTab('video'); },50);
}

// ===== BANNER TRANG CHỦ (Danh mục) — sửa mảng này để đổi nội dung banner =====
var TRANG_CHU_BANNERS=[
  {icon:'🔥',title:'Sale tháng — giảm đến 25%',sub:'Hàng trăm mã đang giảm giá',grad:'linear-gradient(120deg,#C0232A,#8B1A1A)',tab:'sale'},
  {icon:'📦',title:'Sale xả kho — giá tốt nhất',sub:'Hàng tồn kho cần đẩy nhanh, số lượng có hạn',grad:'linear-gradient(120deg,#E65100,#BF360C)',tab:'sale',sf2:'ct2'},
  {icon:'🆕',title:'Mẫu mới về kho',sub:'Xem ngay mẫu gạch vừa cập nhật',grad:'linear-gradient(120deg,#3949AB,#1A237E)',tab:'tra'}
];
function timBanner(i){
  var b=TRANG_CHU_BANNERS[i]; if(!b) return;
  swTab(b.tab);
  if(b.sf2) setTimeout(function(){ setSF2(b.sf2); },0);
}
function renderTrangChuBanners(){
  var el=document.getElementById('dm-banners'); if(!el) return;
  if(!TRANG_CHU_BANNERS.length){ el.innerHTML=''; return; }
  var tid='bnt'+Date.now();
  el.innerHTML=
    '<div style="position:relative;overflow:hidden;border-radius:14px;margin-bottom:6px">'
    +'<div id="'+tid+'" style="display:flex;transition:transform .4s cubic-bezier(.4,0,.2,1);will-change:transform">'
    +TRANG_CHU_BANNERS.map(function(b,i){
      return '<div onclick="timBanner('+i+')" style="flex:0 0 100%;border-radius:14px;padding:18px 20px;background:'+b.grad+';color:#fff;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.12);min-height:96px;display:flex;flex-direction:column;justify-content:center;box-sizing:border-box">'
        +'<div style="font-size:26px;margin-bottom:8px">'+b.icon+'</div>'
        +'<div style="font-size:16px;font-weight:800;margin-bottom:4px;line-height:1.3">'+b.title+'</div>'
        +'<div style="font-size:12px;opacity:.9;line-height:1.5">'+b.sub+'</div>'
        +'</div>';
    }).join('')
    +'</div>'
    +'</div>'
    +(TRANG_CHU_BANNERS.length>1
      ?'<div id="'+tid+'d" style="display:flex;justify-content:center;gap:7px;margin-bottom:14px;padding-top:6px">'
        +TRANG_CHU_BANNERS.map(function(b,i){return '<div class="bcarousel-dot'+(i===0?' on':'')+'" data-i="'+i+'"></div>';}).join('')
        +'</div>'
      :'<div style="margin-bottom:14px"></div>');
  if(TRANG_CHU_BANNERS.length<2) return;
  var track=document.getElementById(tid);
  var dotWrap=document.getElementById(tid+'d');
  var dots=dotWrap?dotWrap.querySelectorAll('.bcarousel-dot'):[];
  var cur=0,timer=null;
  function goBn(idx){
    cur=(idx+TRANG_CHU_BANNERS.length)%TRANG_CHU_BANNERS.length;
    track.style.transform='translateX(-'+cur*100+'%)';
    dots.forEach(function(d,i){d.classList.toggle('on',i===cur);});
  }
  function startAuto(){timer=setInterval(function(){goBn(cur+1);},4000);}
  function stopAuto(){clearInterval(timer);}
  dots.forEach(function(d,i){d.onclick=function(e){e.stopPropagation();stopAuto();goBn(i);startAuto();};});
  startAuto();
  // Swipe support
  var sx=0;
  track.addEventListener('touchstart',function(e){sx=e.touches[0].clientX;stopAuto();},{passive:true});
  track.addEventListener('touchend',function(e){
    var dx=e.changedTouches[0].clientX-sx;
    if(Math.abs(dx)>40) goBn(dx<0?cur+1:cur-1);
    startAuto();
  },{passive:true});
}
// ===== LỚP 1: Danh mục ngành hàng (grid) =====
// Chỉ là màn hình "cửa vào" - bấm vào 1 ô sẽ nhảy sang tab ngành đó
// (dùng lại swTab có sẵn), không tự render danh sách sản phẩm ở đây.
function moDanhMuc(){
  renderDanhMucGrid();
  renderTrangChuBanners();
  swTab('danhmuc');
}
function renderDanhMucGrid(){
  var wrap = document.getElementById('tab-danhmuc');
  var el = document.getElementById('danhmuc-grid');
  if(!el) return;

  // Phụ đề hướng dẫn — chỉ tạo 1 lần, không lặp lại mỗi lần render.
  if(wrap && !document.getElementById('nmuc-sub')){
    var sub = document.createElement('div');
    sub.id = 'nmuc-sub';
    sub.className = 'nmuc-sub';
    sub.textContent = 'Chọn ngành hàng để xem bảng giá và sản phẩm';
    var head = wrap.querySelector('div'); // dòng tiêu đề "Danh mục ngành hàng" có sẵn
    if(head){ head.classList.add('nmuc-title'); head.parentNode.insertBefore(sub, head.nextSibling); }
  }

  el.innerHTML = '';
  el.classList.add('nmuc-grid');
  // Chỉ đếm mã bằng bien du lieu that trong app - khong bia so.
  // Trong lúc dữ liệu còn đang tải/gộp dần (gạch tải trước, CT1/CT2 gộp thêm
  // mã mới vào sau vài giây) -> hiện "..." thay vì số tạm-chưa-đủ, tránh cảm
  // giác trang hiện "số cũ/sai" rồi tự nhảy số vài giây sau.
  var soGach = (typeof DATA!=='undefined' ? DATA.length : 0);
  var soNgoi = (typeof NGOI!=='undefined' ? NGOI.length : 0);
  var soKeo  = (typeof KEO!=='undefined' ? KEO.length : 0);
  var soKinh = (typeof KINH!=='undefined' ? KINH.length : 0);
  var txtGach = (_syncFlags.gach && soGach>0) ? soGach+' mã' : '…';
  var txtNgoi = (_syncFlags.ngoi && soNgoi>0) ? soNgoi+' mã' : '…';
  var txtKeo  = (_syncFlags.keo  && soKeo>0)  ? soKeo+' mã'  : '…';
  var txtKinh = (_syncFlags.kinh && soKinh>0) ? soKinh+' mã' : '…';
  var items = [
    {icon:'🔲', ten:'Gạch',              count:txtGach, tab:'tra',  grad:'linear-gradient(160deg,#FDE4E4,#F8C6C8)'},
    {icon:'🏠', ten:'Ngói',              count:txtNgoi, tab:'ngoi', grad:'linear-gradient(160deg,#F2E3D5,#E3C7A8)'},
    {icon:'🧱', ten:'Keo & bột chà ron', count:txtKeo,  tab:'keo',  grad:'linear-gradient(160deg,#E1F0E4,#BFE0C6)'},
    {icon:'💎', ten:'Gạch kính',         count:txtKinh, tab:'kinh', grad:'linear-gradient(160deg,#E3F2FD,#BBDEFB)'},
    {icon:'🔥', ten:'Đang Sale',         count:null,         tab:'sale', grad:'linear-gradient(160deg,#FFEBEE,#FFCDD2)', sale:true},
    {icon:'🎬', ten:'Video sản phẩm',    count:(typeof danhSachSPCoVideo==='function'?danhSachSPCoVideo().length+' video':null), tab:'video', grad:'linear-gradient(160deg,#EDE7F6,#D1C4E9)'},
    {icon:'🚽', ten:'Thiết bị vệ sinh',  count:null,         tab:'tbvs', grad:'var(--bg2)', soon:true},
    {icon:'🪣', ten:'Sơn nước',          count:null,         tab:'son',  grad:'var(--bg2)', soon:true}
  ];
  items.forEach(function(it){
    var coDuLieu = !!it.tab;

    var card = document.createElement('div');
    card.className = 'nmuc-card' + (it.sale?' nmuc-sale':'') + (it.soon?' nmuc-disabled':'');

    if(it.soon){
      var lock = document.createElement('div');
      lock.className = 'nmuc-lock';
      lock.textContent = '🔒';
      card.appendChild(lock);
    }

    var icon = document.createElement('div');
    icon.className = 'nmuc-icon';
    icon.style.background = it.grad;
    icon.textContent = it.icon;
    card.appendChild(icon);

    var name = document.createElement('div');
    name.className = 'nmuc-name';
    name.textContent = it.ten;
    card.appendChild(name);

    if(it.count){
      var count = document.createElement('div');
      count.className = 'nmuc-count';
      count.textContent = it.count;
      card.appendChild(count);
    }

    if(it.sale){
      var badge = document.createElement('div');
      badge.className = 'nmuc-badge nmuc-badge-sale';
      badge.textContent = 'Đang giảm giá';
      card.appendChild(badge);
    }
    if(it.soon){
      var badgeSoon = document.createElement('div');
      badgeSoon.className = 'nmuc-badge nmuc-badge-soon';
      badgeSoon.textContent = 'Sắp ra mắt';
      card.appendChild(badgeSoon);
    }

    if(coDuLieu){
      card.addEventListener('click', function(){
        if(it.tab==='kinh'){ swTab('tra'); setF('kinh'); }
        else swTab(it.tab);
      });
    }
    el.appendChild(card);
  });
}

// ===== TÌM KIẾM TOÀN BỘ NGÀNH HÀNG =====
// Gộp ket qua tu Gach (DATA) + Ngoi (NGOI) + Keo (KEO). TBVS/Son chua co
// du lieu that nen khong tim - khong bia du lieu gia.
function moTimKiem(){
  swTab('timkiem');
  var inp = document.getElementById('tk-input');
  if(inp){ inp.value=''; setTimeout(function(){ inp.focus(); },50); }
  renderTimKiemResults();
}
function renderTimKiemResults(){
  var resultsEl = document.getElementById('tk-results');
  var hint = document.getElementById('tk-hint');
  var q = (document.getElementById('tk-input').value||'').trim().toUpperCase();
  if(!resultsEl) return;
  resultsEl.innerHTML = '';
  if(!q){
    if(hint) hint.style.display='block';
    return;
  }
  if(hint) hint.style.display='none';

  function khop(p){
    return (p.ma||'').toUpperCase().indexOf(q)>=0 || (p.ten||'').toUpperCase().indexOf(q)>=0 || (p.kc||'').toUpperCase().indexOf(q)>=0;
  }
  var ketQua = [];
  (typeof DATA!=='undefined'?DATA:[]).forEach(function(p){ if(khop(p)) ketQua.push({p:p, nganh:'gach', icon:'🔲', ten:'Gạch'}); });
  (typeof NGOI!=='undefined'?NGOI:[]).forEach(function(p){ if(khop(p)) ketQua.push({p:p, nganh:'ngoi', icon:'🏠', ten:'Ngói'}); });
  (typeof KEO!=='undefined'?KEO:[]).forEach(function(p){ if(khop(p)) ketQua.push({p:p, nganh:'keo', icon:'🧱', ten:'Keo'}); });
  (typeof KINH!=='undefined'?KINH:[]).forEach(function(p){ if(khop(p)) ketQua.push({p:p, nganh:'kinh', icon:'💎', ten:'Gạch kính'}); });

  if(!ketQua.length){
    var empty = document.createElement('div');
    empty.style.cssText = 'padding:40px 10px;text-align:center;color:var(--t2);font-size:13px';
    empty.textContent = 'Không tìm thấy mã nào khớp "'+ (document.getElementById('tk-input').value||'') +'"';
    resultsEl.appendChild(empty);
    return;
  }

  var dem = document.createElement('div');
  dem.style.cssText = 'font-size:12px;color:var(--t2);margin-bottom:8px';
  dem.textContent = ketQua.length+' kết quả';
  resultsEl.appendChild(dem);

  ketQua.slice(0,60).forEach(function(r){
    var p = r.p;
    var row = document.createElement('div');
    row.className = 'tk-row';
    row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:11px 10px;background:var(--bg1);border:1px solid var(--bd);border-radius:12px;margin-bottom:8px;cursor:pointer';

    var badge = document.createElement('div');
    badge.style.cssText = 'flex-shrink:0;width:36px;height:36px;border-radius:10px;background:var(--bg2);display:flex;align-items:center;justify-content:center;font-size:17px';
    badge.textContent = r.icon;
    row.appendChild(badge);

    var mid = document.createElement('div');
    mid.style.cssText = 'flex:1;min-width:0';
    var ten = document.createElement('div');
    ten.style.cssText = 'font-size:13.5px;font-weight:700;color:var(--t1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
    ten.textContent = p.ma||'';
    var sub = document.createElement('div');
    sub.style.cssText = 'font-size:11.5px;color:var(--t2);margin-top:2px';
    sub.textContent = r.ten + (p.kc?(' · '+p.kc):'');
    mid.appendChild(ten); mid.appendChild(sub);
    row.appendChild(mid);

    var gia = document.createElement('div');
    gia.style.cssText = 'flex-shrink:0;font-size:13px;font-weight:800;color:var(--red)';
    gia.textContent = (p.le>0) ? fmt(p.le) : '';
    row.appendChild(gia);

    row.addEventListener('click', function(){
      if(r.nganh==='gach'){ swTab('tra'); showDP(p.ma); }
      else if(r.nganh==='ngoi'){ swTab('ngoi'); showNgoi(p.ma); }
      else if(r.nganh==='keo'){ swTab('keo'); showKeo(p.ma); }
      else if(r.nganh==='kinh'){ swTab('tra'); setF('kinh'); }
    });

    resultsEl.appendChild(row);
  });
}

