var curSortTon=false;
function tonKhoTongCuaMa(ma){
  var tk=(typeof timTonKhoTheoQuyen==='function')?timTonKhoTheoQuyen(ma):null;
  return (tk&&tk.tong)?tk.tong:0;
}
