// ===== BỘ LỌC DỌC DESKTOP (tab Gạch) =====
var curSortGia=false;      // sắp xếp giá lẻ thấp → cao
var curLocGia='';          // '', lt250, 250_350, 350_500, gt500
var curLocCT={cl:false,sale:false};

function khopLocGia(p){
  if(!curLocGia) return true;
  var le=p.le||0;
  if(curLocGia==='lt250')   return le>0&&le<250000;
  if(curLocGia==='250_350') return le>=250000&&le<=350000;
  if(curLocGia==='350_500') return le>350000&&le<=500000;
  if(curLocGia==='gt500')   return le>500000;
  return true;
}
function khopLocCT(p){
  if(!curLocCT.cl&&!curLocCT.sale) return true;
  if(curLocCT.cl && p.gio==='★') return true;
  if(curLocCT.sale && p._fromCT) return true;
  return false;
}
function fsApply(){ curPage=0; render(); }
function fsSetSort(v){ curSortGia=(v==='gia'); fsApply(); }
function fsSetGia(v){ curLocGia=v; fsApply(); }
function fsToggleCT(k){ curLocCT[k]=!curLocCT[k]; fsApply(); }
function fsSetAttr(key,val){
  locNangCao[key]=val;
  if(typeof capNhatBadgeLocNangCao==='function') capNhatBadgeLocNangCao();
  fsApply();
}
function fsClear(){
  curSortGia=false; curLocGia=''; curLocCT={cl:false,sale:false};
  if(typeof LOC_NANG_CAO_FIELDS!=='undefined') LOC_NANG_CAO_FIELDS.forEach(function(f){ locNangCao[f.key]=''; });
  if(typeof capNhatBadgeLocNangCao==='function') capNhatBadgeLocNangCao();
  buildFilterSide();
  fsApply();
}
function buildFilterSide(){
  var el=document.getElementById('filter-side');
  if(!el) return;
  var h='';
  h+='<div style="display:flex;justify-content:space-between;align-items:center">'
    +'<span style="font-size:14px;font-weight:800">Bộ lọc</span></div>';
  // Sắp xếp
  h+='<div class="fs-hdr">Sắp xếp</div>'
    +'<label class="fs-row"><input type="radio" name="fs-sort" '+(!curSortGia?'checked':'')+' onchange="fsSetSort(\'\')"/> Mặc định</label>'
    +'<label class="fs-row"><input type="radio" name="fs-sort" '+(curSortGia?'checked':'')+' onchange="fsSetSort(\'gia\')"/> Giá thấp → cao</label>';
  // Giá lẻ
  var giaOpts=[['','Tất cả'],['lt250','Dưới 250.000'],['250_350','250.000 – 350.000'],['350_500','350.000 – 500.000'],['gt500','Trên 500.000']];
  h+='<div class="fs-hdr">Giá lẻ (đ/m²)</div>';
  giaOpts.forEach(function(o){
    h+='<label class="fs-row"><input type="radio" name="fs-gia" '+(curLocGia===o[0]?'checked':'')+' onchange="fsSetGia(\''+o[0]+'\')"/> '+o[1]+'</label>';
  });
  // Chương trình
  h+='<div class="fs-hdr">Chương trình</div>'
    +'<label class="fs-row"><input type="checkbox" '+(curLocCT.cl?'checked':'')+' onchange="fsToggleCT(\'cl\')"/> ★ Chiến lược</label>'
    +'<label class="fs-row"><input type="checkbox" '+(curLocCT.sale?'checked':'')+' onchange="fsToggleCT(\'sale\')"/> 🔥 Đang Sale (CT1/CT2)</label>';
  // Thuộc tính (Màu / Công năng / Tính năng / Hoa văn / Men) — dropdown như lọc nâng cao
  if(typeof LOC_NANG_CAO_FIELDS!=='undefined' && typeof thuocTinhMap!=='undefined' && Object.keys(thuocTinhMap).length){
    var giaTri={};
    LOC_NANG_CAO_FIELDS.forEach(function(f){ giaTri[f.key]={}; });
    Object.keys(thuocTinhMap).forEach(function(ma){
      var t=thuocTinhMap[ma];
      LOC_NANG_CAO_FIELDS.forEach(function(f){ if(t[f.key]) giaTri[f.key][t[f.key]]=true; });
    });
    h+='<div class="fs-hdr">Thuộc tính</div>';
    LOC_NANG_CAO_FIELDS.forEach(function(f){
      var opts=Object.keys(giaTri[f.key]).sort();
      if(!opts.length) return;
      h+='<span class="fs-lbl">'+f.label+'</span>'
        +'<select onchange="fsSetAttr(\''+f.key+'\',this.value)">'
        +'<option value="">Tất cả</option>'
        +opts.map(function(o){ return '<option value="'+o.replace(/"/g,'&quot;')+'"'+(locNangCao[f.key]===o?' selected':'')+'>'+o+'</option>'; }).join('')
        +'</select>';
    });
  }
  h+='<div id="fs-count"></div>'
    +'<button id="fs-clear" onclick="fsClear()">Xóa hết bộ lọc</button>';
  el.innerHTML=h;
}
// Các panel cố định (sidebar kích cỡ, bộ lọc, giỏ hàng) bám đúng mép dưới header —
// header có thể cao hơn 57px khi tên công ty xuống 2 dòng, tránh sidebar đè lên header
function capNhatTopPanels(){
  if((window.innerWidth||0)<768) return;
  var tb=document.querySelector('.topbar');
  if(!tb) return;
  var h=Math.max(tb.offsetHeight,57);
  ['size-sidebar','filter-side','tab-don','sale-size-sidebar'].forEach(function(id){
    var el=document.getElementById(id);
    // setProperty important để thắng quy tắc top:57px !important trong CSS
    if(el) el.style.setProperty('top', h+'px', 'important');
  });
}
window.addEventListener('resize',capNhatTopPanels);
setTimeout(capNhatTopPanels,300);
// Resize cửa sổ (thu/phóng, kéo qua lại 2 màn hình) phải tính lại việc hiện/ẩn
// bộ lọc dọc + số cột lưới — nếu không, display:block cũ (lúc còn >=1200px) bị
// kẹt lại khi thu nhỏ xuống <1200px, đè lệch layout (Bộ lọc/Thuộc tính chồng lên đầu trang).
var _rzTimer=null;
window.addEventListener('resize',function(){
  clearTimeout(_rzTimer);
  _rzTimer=setTimeout(function(){
    capNhatFilterSide();
    if(typeof render==='function') render();
  },150);
});

// Hiện/ẩn bộ lọc dọc: chỉ desktop rộng + đang ở tab Gạch
function capNhatFilterSide(){
  var el=document.getElementById('filter-side');
  if(!el) return;
  var tra=document.getElementById('tab-tra');
  var show=!!(tra&&tra.classList.contains('on')) && (window.innerWidth||0)>=1200 && curF!=='kinh';
  el.style.display=show?'block':'none';
  document.body.classList.toggle('fs-on',show);
  if(show && !el.innerHTML) buildFilterSide();
}

function render(){
  var q=document.getElementById('sq').value.trim().toUpperCase();
  // Nếu filter gạch kính → hiển thị trong tab Gạch cùng với nút thêm vào đơn
  if(curF==='kinh'){
    capNhatFilterSide();
    renderKinhInGach();
    return;
  }
  var list = DATA;
  if(curF==='porcelain') list=list.filter(function(p){return p.cat==='porcelain';});
  else if(curF==='ceramic') list=list.filter(function(p){return p.cat==='ceramic';});
  else if(curF==='sale'){ renderSale(); return; }
  if(curSize&&curSize!=='all') list=list.filter(function(p){return p.kc===curSize||p.kc.toLowerCase()===curSize.toLowerCase();});
  if(hasLocNangCao()) list=list.filter(function(p){return khopLocNangCao(p.ma);});
  if(q) list=list.filter(function(p){return p.ma.toUpperCase().includes(q)||p.kc.includes(q);});
  // Bộ lọc dọc desktop: khoảng giá lẻ + chương trình
  if(curLocGia) list=list.filter(khopLocGia);
  if(curLocCT.cl||curLocCT.sale) list=list.filter(khopLocCT);
  // Sắp xếp theo tồn kho nhiều nhất (nút 📦 Tồn nhiều cạnh bộ lọc)
  // Đến hết 03/08/2026 (chương trình CT1/CT2 hiện tại kết thúc): ưu tiên
  // đẩy SKU đang Sale/Xả kho lên đầu để đẩy hàng tồn trước khi hết hạn.
  if(curSortTon){
    var uuTienCT123=new Date() < new Date('2026-08-04T00:00:00+07:00');
    list=list.slice().sort(function(a,b){
      if(uuTienCT123){
        var aCT=isDangSaleCT123(a.ma)?1:0, bCT=isDangSaleCT123(b.ma)?1:0;
        if(aCT!==bCT) return bCT-aCT;
      }
      return tonKhoTongCuaMa(b.ma)-tonKhoTongCuaMa(a.ma);
    });
  } else if(curSortGia){
    list=list.slice().sort(function(a,b){ return (a.le||1e12)-(b.le||1e12); });
  }
  // Cập nhật bộ đếm trên bộ lọc dọc
  var fsc=document.getElementById('fs-count');
  if(fsc) fsc.textContent='Đang hiện '+list.length+' / '+DATA.length+' mã';
  capNhatFilterSide();
  var totalItems=list.length;
  var totalPages=Math.max(1,Math.ceil(totalItems/20));
  if(curPage>=totalPages) curPage=totalPages-1;
  var shown=list.slice(curPage*20,(curPage+1)*20);
  var startN=curPage*20+1, endN=Math.min((curPage+1)*20,totalItems);
  document.getElementById('pcount').textContent=totalItems+' mã'+(totalItems>0?' · hiển thị '+startN+'–'+endN:'');
  renderDanhMucGrid();
  renderTrangChuBanners();
  var el=document.getElementById('plist'); el.innerHTML='';
  // Skeleton khi data chưa tải xong
  if(!DATA||DATA.length===0){
    var skHtml='';
    for(var sk=0;sk<8;sk++) skHtml+='<div class="sk-card"><div class="sk-img"></div><div class="sk-body"><div class="sk-line sk-w80"></div><div class="sk-line sk-w60"></div><div class="sk-line sk-w90"></div><div class="sk-line sk-w50"></div></div></div>';
    el.innerHTML='<div class="sk-grid">'+skHtml+'</div>';
    return;
  }
  // Empty state khi filter không có kết quả
  if(shown.length===0){
    el.innerHTML='<div class="empty-state">'
      +'<div class="empty-icon">🔍</div>'
      +'<div class="empty-title">Không tìm thấy sản phẩm nào</div>'
      +'<div class="empty-sub">Thử thay đổi bộ lọc hoặc xóa từ khóa tìm kiếm</div>'
      +'<button onclick="document.getElementById(\'sq\').value=\'\';setSize(\'all\');curLocGia=\'\';curLocCT={};render()" class="empty-reset-btn">Xóa tất cả bộ lọc</button>'
      +'</div>';
    return;
  }
  shown.forEach(function(p){
    var hasSale=p.gio==='●' && p.ns>0; // Sale thật: gio=● VÀ có giá ns thật
    var star=p.gio==='★'?' <span class="badge" style="background:#FDECEA;color:#8B0000;font-size:10px;padding:1px 6px;border-radius:4px;font-weight:700">★ CL</span>'
             :p.gio==='●'?' <span class="badge" style="background:#E8F5E9;color:#1B5E20;font-size:10px;padding:1px 6px;border-radius:4px;font-weight:700">🔥 Sale</span>':'';
    var saleDot=hasSale?'<span class="sale-dot"></span>':'';
    var priceNhan=p.nhan>0?p.nhan.toLocaleString('vi-VN')+'đ':'–';
    var priceGiao=p.giao>0?p.giao.toLocaleString('vi-VN')+'đ':'–';
    var priceNs=p.ns>0?p.ns.toLocaleString('vi-VN')+'đ':'–';
    var imgUrl=timAnh(p.ma)||'';
    var isDesktop=window.innerWidth>=768;
    var div=document.createElement('div'); div.className='mk';
    if(isDesktop){
      // Desktop: ảnh nhỏ trái ~30%, thông tin đầy đủ bên phải
      div.style.cssText='cursor:pointer;overflow:hidden;display:flex;flex-direction:column;padding:0 !important';
      var badgeHtml=p.gio==='★'
        ?'<span style="background:#8B0000;color:#fff;font-size:9px;font-weight:700;padding:2px 7px;border-radius:4px;white-space:nowrap">★ CL</span>'
        :p.gio==='●'
        ?'<span style="background:#1B5E20;color:#fff;font-size:9px;font-weight:700;padding:2px 7px;border-radius:4px;white-space:nowrap">🔥 Sale</span>'
        :'';
      // Tra giá sale CT1/CT2 (sale tháng) — field: nk=nhận kho, gh=giao hàng
      var ct1Info=(window.CT1_DATA||[]).find(function(x){return x.ma===p.ma;})
                ||(window.CT2_DATA||[]).find(function(x){return x.ma===p.ma;});
      var nkSale=ct1Info?(ct1Info.nk||ct1Info.ns||0):0;
      var ghSale=ct1Info?(ct1Info.gh||ct1Info.gs||0):0;
      var hasCT1Sale=nkSale>0;
      var hasNsSale=!hasCT1Sale&&p.ns>0&&p.ns<p.nhan;
      var giaGiao=ghSale>0?ghSale.toLocaleString('vi-VN')+'đ':((hasSale||hasNsSale)&&p.gs>0?p.gs.toLocaleString('vi-VN')+'đ':priceGiao);
      var giaNhan=hasCT1Sale?nkSale.toLocaleString('vi-VN')+'đ':(hasNsSale||hasSale?priceNs:priceNhan);
      var tk=timTonKhoTheoQuyen(p.ma);
      var tkDot=tk?(tk.tier&&tk.tier.nhanh>0?'🟢':tk.tier&&tk.tier.mai>0?'🟡':'🔴'):'';
      var tkText=tk?tkDot+' Còn '+fmtTkCard(tk.tong,tk.dvt):'';
      var tkColor=tk?(tk.tier&&tk.tier.nhanh>0?'#2E7D32':tk.tier&&tk.tier.mai>0?'#E65100':'#C62828'):'#bbb';
      var noImgHtml='<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:6px"><span style="font-size:32px">📷</span><span style="font-size:10px;color:#bbb">Chưa có ảnh</span></div>';
      var overlayBadges=badgeHtml
        ?'<div style="position:absolute;top:8px;left:8px;display:flex;gap:4px;flex-wrap:wrap">'+badgeHtml+'</div>'
        :'';
      div.innerHTML=
        '<div class="mk-thumb" style="width:100%;height:160px;background:#F0EEEC;position:relative;overflow:hidden;flex-shrink:0">'
        +(imgUrl?'<img src="'+imgUrl+'" loading="lazy" decoding="async" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover" onerror="this.style.display=\'none\'">':'')
        +noImgHtml
        +overlayBadges
        +'<div class="mk-hover-overlay">Xem chi tiết</div>'
        +'</div>'
        +'<div style="padding:12px;display:flex;flex-direction:column;gap:5px;flex:1">'
        +'<div style="font-size:11px;color:#888;display:flex;align-items:center;gap:5px"><span>'+p.kc+'</span></div>'
        +'<div style="font-size:13px;font-weight:700;color:#111;line-height:1.3;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;word-break:break-all">'+p.ma+'</div>'
        +(p.le>0?'<div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font-size:11px;color:#999">Giá lẻ</span><span style="font-size:12px;font-weight:600;color:#555">'+p.le.toLocaleString('vi-VN')+'đ</span></div>':'')
        +'<div style="display:flex;justify-content:space-between;align-items:baseline">'
        +'<span style="font-size:11px;color:#999">Nhận kho</span>'
        +'<span>'
        +(hasCT1Sale||hasNsSale||hasSale?'<span style="font-size:11px;color:#bbb;text-decoration:line-through;margin-right:4px">'+priceNhan+'</span>':'')
        +'<span style="font-size:14px;font-weight:800;color:#C0232A">'+giaNhan+'</span>'
        +'</span>'
        +'</div>'
        +'<div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font-size:11px;color:#999">Giao hàng</span><span style="font-size:13px;font-weight:700;color:#1565C0">'+giaGiao+'</span></div>'
        +(tkText?'<div style="font-size:11px;font-weight:600;color:'+tkColor+';margin-top:2px">'+tkText+'</div>':'')
        +'</div>';
    } else {
      // Mobile: layout dọc — ảnh + tên/kích cỡ + giá lẻ/nhận kho/giao + tồn kho
      var mCt1=(window.CT1_DATA||[]).find(function(x){return x.ma===p.ma;})
             ||(window.CT2_DATA||[]).find(function(x){return x.ma===p.ma;});
      var mNkSale=mCt1?(mCt1.nk||mCt1.ns||0):0;
      var mGhSale=mCt1?(mCt1.gh||mCt1.gs||0):0;
      var mHasCT1=mNkSale>0;
      var mHasNsSale=!mHasCT1&&p.ns>0&&p.ns<p.nhan;
      var mGiaNhan=mHasCT1?mNkSale.toLocaleString('vi-VN')+'đ':(mHasNsSale||hasSale?priceNs:priceNhan);
      var mGiaGiao=mGhSale>0?mGhSale.toLocaleString('vi-VN')+'đ':((mHasNsSale||hasSale)&&p.gs>0?p.gs.toLocaleString('vi-VN')+'đ':priceGiao);
      var mGiaGoc=mHasCT1?priceNhan:(mHasNsSale||hasSale?priceNhan:'');
      var mTk=timTonKhoTheoQuyen(p.ma);
      var mTkDot=mTk?(mTk.tier&&mTk.tier.nhanh>0?'🟢':mTk.tier&&mTk.tier.mai>0?'🟡':'🔴'):'';
      var mTkText=mTk?mTkDot+' Còn '+fmtTkCard(mTk.tong,mTk.dvt):'';
      var mTkColor=mTk?(mTk.tier&&mTk.tier.nhanh>0?'#2E7D32':mTk.tier&&mTk.tier.mai>0?'#E65100':'#C62828'):'#bbb';
      div.style.cssText='padding:12px;cursor:pointer;align-items:flex-start';
      var mImgHtml='<div style="width:96px;flex-shrink:0;margin-right:10px;display:flex;flex-direction:column;align-items:center;gap:4px">'
        +'<div class="mk-thumb" style="width:96px;height:96px;border-radius:10px;background:#F0EEEC;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden">'
        +(imgUrl?'<img src="'+imgUrl+'" loading="lazy" decoding="async" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:8px" onerror="this.style.display=\'none\'">'
          :'<div style="display:flex;flex-direction:column;align-items:center;gap:2px"><span style="font-size:20px">📷</span><span style="font-size:8px;color:#bbb;text-align:center;line-height:1.2">Chưa<br>có ảnh</span></div>')
        +'</div>'
        +'<div style="display:flex;align-items:center;justify-content:center;gap:4px;width:100%;flex-wrap:wrap">'
        +'<span style="font-size:10px;color:var(--t2);white-space:nowrap">'+p.kc+'</span>'
        +(star?star:'')
        +'</div>'
        +'</div>';
      div.innerHTML=mImgHtml
        +'<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:3px">'
        +'<div>'
        +'<span style="font-size:13px;font-weight:700;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block">'+p.ma+saleDot+'</span>'
        +'</div>'
        +'<div style="height:1px;background:var(--bd);margin:1px 0"></div>'
        +(p.le>0?'<div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font-size:10px;color:#999">Giá lẻ</span><span style="font-size:11px;color:#555;font-weight:600">'+p.le.toLocaleString('vi-VN')+'đ</span></div>':'')
        +'<div style="display:flex;justify-content:space-between;align-items:baseline">'
        +'<span style="font-size:10px;color:#999">Giá ĐL nhận kho</span>'
        +'<span>'
        +(mGiaGoc?'<span style="font-size:10px;color:#bbb;text-decoration:line-through;margin-right:3px">'+mGiaGoc+'</span>':'')
        +'<span style="font-size:13px;font-weight:800;color:#C0232A">'+mGiaNhan+'</span>'
        +'</span>'
        +'</div>'
        +'<div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font-size:10px;color:#999">→ Giá ĐL giao</span><span style="font-size:11px;font-weight:700;color:#1565C0">'+mGiaGiao+'</span></div>'
        +(mTkText?'<div style="font-size:10px;font-weight:600;color:'+mTkColor+';margin-top:1px">'+mTkText+'</div>':'')
        +'</div>';
    }
    div.addEventListener('click',function(){showDP(p.ma);});
    el.appendChild(div);
    registerAutoCycle(div.querySelector('.mk-thumb'), p.ma);
  });
  // Render pagination
  var pagEl=document.getElementById('pagination');
  if(pagEl){
    pagEl.innerHTML='';
    if(totalPages>1){
      // Prev
      var prev=document.createElement('button');
      prev.className='pag-btn'; prev.textContent='‹';
      prev.disabled=(curPage===0);
      prev.onclick=function(){goPage(curPage-1);};
      pagEl.appendChild(prev);
      // Pages
      var startP=Math.max(0,curPage-2), endP=Math.min(totalPages-1,curPage+2);
      if(startP>0){var d=document.createElement('span');d.textContent='…';d.style.color='var(--t3)';pagEl.appendChild(d);}
      for(var pi=startP;pi<=endP;pi++){
        var pb=document.createElement('button');
        pb.className='pag-btn'+(pi===curPage?' on':'');
        pb.textContent=pi+1;
        (function(pp){pb.onclick=function(){goPage(pp);};})(pi);
        pagEl.appendChild(pb);
      }
      if(endP<totalPages-1){var d2=document.createElement('span');d2.textContent='…';d2.style.color='var(--t3)';pagEl.appendChild(d2);}
      // Next
      var next=document.createElement('button');
      next.className='pag-btn'; next.textContent='›';
      next.disabled=(curPage===totalPages-1);
      next.onclick=function(){goPage(curPage+1);};
      pagEl.appendChild(next);
    }
  }

}
function showDP(ma){
  var p=DATA.find(function(x){return x.ma===ma;}); if(!p) return;
  curP_ma=ma;
  document.getElementById('dp-ma').textContent=p.ma;
  document.getElementById('dp-kc').textContent='Kích cỡ: '+p.kc+(p.gio?' · '+p.gio+(p.gio==='★'?' Chiến lược':' Chủ lực'):'');
  // Quy cách: số viên/thùng, kg/thùng
  var qcEl = document.getElementById('dp-quycach');
  if(qcEl){
    var qc = getQuyCach(p.kc, p.cat);
    if(qc){
      qcEl.style.display='block';
      qcEl.textContent = '📦 '+qc.vien+' viên/thùng · '+qc.m2+'m²/thùng'+(qc.kg?' · '+qc.kg+'kg/thùng':'');
    } else {
      qcEl.style.display='none';
    }
  }
  document.getElementById('dp-le').textContent=fmt(p.le);
  // Ô "Nhận kho"/"Giao hàng" luôn hiện giá THƯỜNG (chưa sale) - giá Sale đã
  // có mục riêng "GIÁ SALE" bên dưới, không trộn vào đây nữa (theo yêu cầu).
  var isSaleItem = p._fromCT==='CT1' || p._fromCT==='CT2';
  var dispNhan = p.nhan>0 ? p.nhan : (p.ns||0);
  var dispGiao = p.giao>0 ? p.giao : (p.gs||0);
  document.getElementById('dp-nhan').textContent = fmt(dispNhan);
  document.getElementById('dp-giao').textContent = fmt(dispGiao);
  // Cập nhật label GIÁ ĐẠI LÝ → GIÁ SALE nếu là SP từ CT1/CT2
  var giaDlLabel = document.getElementById('dp-gia-dl-label');
  if(giaDlLabel){
    if(p._fromCT==='CT1') giaDlLabel.innerHTML='🔥 GIÁ SALE THÁNG <span style="font-size:10px;background:#E8F5E9;color:#1B5E20;padding:1px 6px;border-radius:4px">CT1</span>';
    else if(p._fromCT==='CT2') giaDlLabel.innerHTML='📦 GIÁ XẢ KHO <span style="font-size:10px;background:#FFF3E0;color:#E65100;padding:1px 6px;border-radius:4px">CT2</span>';
    else giaDlLabel.textContent='GIÁ ĐẠI LÝ';
  }
  // Tra giá sale từ CT1_DATA / CT2_DATA (nếu đã load)
  // Lưu ý: mergeCTintoDATA gắn p.ns = c.nk (trường nk), không phải c.ns.
  // Chương trình CT150 đã kết thúc - không còn ưu tiên ct150nk/ct150gh nữa,
  // chỉ dùng giá Sale CT1/CT2 hiện hành (nk/gh).
  var saleInfo = CT1_DATA.find(function(x){return x.ma===ma;})
               || CT2_DATA.find(function(x){return x.ma===ma;});
  var ns_sale = saleInfo ? (saleInfo.nk||saleInfo.ns||0) : (p.ns||0);
  var gs_sale = saleInfo ? (saleInfo.gh||saleInfo.gs||0) : (p.gs||0);
  // Fallback: nếu saleInfo không có giá nhưng p đã được gắn _fromCT thì dùng p.ns/p.gs
  if(!ns_sale && isSaleItem) ns_sale = p.ns||0;
  if(!gs_sale && isSaleItem) gs_sale = p.gs||0;
  var loai_sale = saleInfo ? saleInfo.loai_sale : (isSaleItem?(p._fromCT==='CT1'?'ct1':'ct2'):null);
  // Hiện "GIÁ SALE" bình thường cho cả CT1 lẫn CT2 (giá thường + giá sale
  // song song). Chỉ tính là "đang Sale" khi SP thực sự thuộc CT1/CT2 (có
  // saleInfo hoặc đã gắn _fromCT) - không chỉ dựa vào giá > 0, vì gs_sale
  // mặc định fallback về giá giao thường (luôn > 0) khiến mọi SP đều bị
  // hiện nhầm "GIÁ SALE".
  var hasSale = (isSaleItem || !!saleInfo) && (ns_sale>0 || gs_sale>0);
  // Giá xả kho đặc biệt (chỉ CT2) - tái sử dụng cột ct150nk/ct150gh cũ, giờ
  // mang ý nghĩa mới: 1 mức giá xả kho riêng, chỉ có ở 1 số mã CT2.
  var xaKhoNK = (saleInfo && loai_sale==='ct2') ? (saleInfo.ct150nk||0) : 0;
  var xaKhoGH = (saleInfo && loai_sale==='ct2') ? (saleInfo.ct150gh||0) : 0;
  var hasXaKho = xaKhoNK>0 || xaKhoGH>0;
  var saleSec = document.getElementById('dp-sale-section');
  var showSec = hasSale || hasXaKho;
  saleSec.style.display = showSec ? 'block' : 'none';
  var saleGridWrap = document.getElementById('dp-sale-grid-wrap');
  if(saleGridWrap) saleGridWrap.style.display = hasSale ? 'block' : 'none';
  var xaKhoWrap = document.getElementById('dp-xakho-wrap');
  if(xaKhoWrap) xaKhoWrap.style.display = hasXaKho ? 'block' : 'none';
  if(hasXaKho){
    document.getElementById('dp-xk-nk').textContent = xaKhoNK>0 ? fmt(xaKhoNK) : '–';
    document.getElementById('dp-xk-gh').textContent = xaKhoGH>0 ? fmt(xaKhoGH) : '–';
  }
  if(hasSale){
    document.getElementById('dp-ns').textContent=fmt(ns_sale);
    document.getElementById('dp-gs').textContent=fmt(gs_sale);
    // base = giá thường (trước sale): p.nhan ưu tiên, fallback sang saleInfo.nhan
    var base=p.nhan||p.giao||(saleInfo?(saleInfo.nhan||saleInfo.giao||0):0);
    var saleP=ns_sale||gs_sale;
    var saveEl=document.getElementById('dp-save');
    if(base&&saleP&&base>saleP){
      var save=base-saleP; var pct=Math.round(save/base*100);
      saveEl.textContent='Tiết kiệm '+save.toLocaleString('vi-VN')+'đ/m² (giảm '+pct+'%)';
      saveEl.style.display='block';
    } else if(isSaleItem){
      saveEl.textContent=(loai_sale==='ct1'?'🔥 Sale tháng CT1 – Giá ưu đãi':'📦 Xả kho CT2 – Giá ưu đãi đặc biệt');
      saveEl.style.display='block';
    } else {
      saveEl.style.display='none';
    }
  } else {
    var saveEl2=document.getElementById('dp-save');
    if(saveEl2) saveEl2.style.display='none';
  }
  if(showSec){
    // Hiện badge loại sale
    var badgeEl = document.getElementById('dp-sale-badge');
    if(badgeEl){
      if(hasSale && loai_sale==='ct1') { badgeEl.style.display='inline'; badgeEl.textContent='🗓️ Sale tháng'; badgeEl.style.cssText='display:inline;font-size:10px;background:#E8F5E9;color:#2E7D32;padding:2px 6px;border-radius:4px;margin-left:6px'; }
      else if(hasSale && loai_sale==='ct2') { badgeEl.style.display='inline'; badgeEl.textContent='📦 Xả kho'; badgeEl.style.cssText='display:inline;font-size:10px;background:#FFF3E0;color:#E65100;padding:2px 6px;border-radius:4px;margin-left:6px'; }
      else badgeEl.style.display='none';
    }
  } else {
    var badgeEl2 = document.getElementById('dp-sale-badge');
    if(badgeEl2) badgeEl2.style.display='none';
  }
  dpSetTab('gia');
  document.getElementById('dp').style.display='block';
  var isDesk=(window.innerWidth||document.documentElement.clientWidth||0)>=768;
  if(isDesk) document.body.classList.add('dp-open');
  // Modal giữa màn hình (desktop) lẫn bottom-sheet (mobile) đều cần nền mờ phía sau
  var bd=document.getElementById('dp-backdrop'); if(bd) bd.classList.add('on');
  if(document.getElementById('dp-scroll')) document.getElementById('dp-scroll').scrollTop=0;
  // Reset qty input về m² mặc định
  dpUnit='m2';
  var qtyInp=document.getElementById('dp-qty-input');
  if(qtyInp) qtyInp.value=1;
  setTimeout(function(){ setDpUnit('m2'); },10);
  loadImg(ma);
  renderDpRelated(p);
  renderDpExtra(ma);
}
// Sản phẩm liên quan: cùng kích cỡ (kc), khác mã, ưu tiên còn ảnh, tối đa 8
function renderDpRelated(p){
  var wrap=document.getElementById('dp-related-wrap');
  var el=document.getElementById('dp-related');
  if(!wrap||!el) return;
  var list=DATA.filter(function(x){ return x.kc===p.kc && x.ma!==p.ma; }).slice(0,8);
  if(!list.length){ wrap.style.display='none'; el.innerHTML=''; return; }
  wrap.style.display='block';
  el.innerHTML=list.map(function(x){
    var img=timAnh(x.ma)||'';
    return '<div onclick="showDP(\''+x.ma+'\')" style="flex:0 0 84px;cursor:pointer;text-align:center">'
      +'<div style="width:84px;height:84px;border-radius:10px;overflow:hidden;background:var(--bg2);display:flex;align-items:center;justify-content:center">'
      +(img?'<img src="'+img+'" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display=\'none\'">':'<span style="font-size:22px">📷</span>')
      +'</div>'
      +'<div style="font-size:10px;color:var(--t2);margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+x.ma+'</div>'
      +'</div>';
  }).join('');
}
// Chuyển tab Giá/Mô tả/Video - dùng chung cho popup Gạch (dp), Ngói (nd), Keo (kd)
function setTabGeneric(prefix, tab){
  // Panel "gia" của Ngói/Keo dùng layout ngang (ảnh trái/giá phải) trên desktop
  // (display:flex qua CSS @media) nhưng vẫn stack dọc trên mobile (display:block).
  var isNkGiaPanel = (prefix==='nd'||prefix==='kd');
  var desktopFlex = isNkGiaPanel && window.matchMedia('(min-width:768px)').matches;
  ['gia','mota','video'].forEach(function(t){
    var panel=document.getElementById(prefix+'-panel-'+t);
    var btn=document.getElementById(prefix+'-tbtn-'+t);
    if(panel){
      if(t!==tab) panel.style.display='none';
      else panel.style.display=(t==='gia'&&desktopFlex)?'flex':'block';
    }
    if(btn){ btn.classList.toggle('dp-tbtn-active',t===tab); }
  });
}
function dpSetTab(tab){ setTabGeneric('dp', tab); }
function closeDp(){
  document.getElementById('dp').style.display='none';
  document.body.classList.remove('dp-open');
  var bd=document.getElementById('dp-backdrop'); if(bd) bd.classList.remove('on');
  if((window.innerWidth||document.documentElement.clientWidth||0)>=768) renderDon();
}
// --- TAB 2 Sale ---
function setSF(f){
  curSF=f;
  ['all','porcelain','ceramic'].forEach(function(x){
    var b=document.getElementById('sf-'+x); if(b) b.classList.toggle('on',x===f);
  });
  renderSale();
}
