        +'<span style="font-weight:700;color:#C0232A">'+fmt(saleP)+'</span></div>'
        +(p.nhan_kv>0?'<div style="display:flex;justify-content:space-between;font-size:11px">'
        +'<span style="color:var(--t2)">Không vét</span>'
        +'<span style="color:var(--t1)">'+fmt(p.nhan_kv)+'</span></div>':'')
        +'</div>';
