  var giaoVal=use2?p.giao2:p.giao;
  var tierLabel=use2?' (≥50 bao)':' (<50 bao)';
  var color=use2?'#388E3C':'#7B1FA2';
  document.getElementById('kd-tien-nhan').textContent=(nhanVal*sl).toLocaleString('vi-VN')+'đ'+tierLabel;
  document.getElementById('kd-tien-nhan').style.color=color;
  document.getElementById('kd-tien-giao').textContent=(giaoVal*sl).toLocaleString('vi-VN')+'đ'+tierLabel;
  document.getElementById('kd-tien-giao').style.color=color;
