// Dựng nội dung báo giá text (dùng chung cho popup chi tiết SP + Zalo nhanh)
function layNoiDungBaoGia(ma){
  var p=DATA.find(function(x){return x.ma===ma;});
  if(!p) return '';

  // Lấy thêm data từ CT1/CT2 nếu SP từ Sale
  var ctData = CT1_DATA.find(function(x){return x.ma===p.ma;})
            || CT2_DATA.find(function(x){return x.ma===p.ma;});

  // isSale = chỉ khi SP từ CT1/CT2 (có đánh dấu _fromCT)
  // SP thường dù có ns>0 (từ merge) vẫn KHÔNG phải Sale
  var isSale = p._fromCT==='CT1' || p._fromCT==='CT2';
  var isCT2  = p._fromCT==='CT2';

  var f = function(n){ return n>0?n.toLocaleString('vi-VN')+'đ/m²':'–'; };

  // Lấy đúng giá
  var le      = p.le      || (ctData?ctData.le:0)       || 0;
  var nk      = p.nhan    || 0;  // Giá ĐL NK thường
  var gh      = p.giao    || 0;  // Giá ĐL GH thường
  var saleNK  = p.ns      || (ctData?ctData.nk:0)      || 0;  // Giá Sale NK
  var saleGH  = p.gs      || (ctData?ctData.gh:0)      || 0;  // Giá Sale GH
  var vetNK   = p.ct150nk || (ctData?ctData.ct150nk:0) || 0;  // Giá VÉT KHO NK (chỉ CT2)
  var vetGH   = p.ct150gh || (ctData?ctData.ct150gh:0) || 0;  // Giá VÉT KHO GH (chỉ CT2)
  // SP thường: nếu nk=0 nhưng ns>0 (do merge) → vẫn dùng ns làm NK thường
  if(!isSale && nk===0 && saleNK>0) nk = saleNK;
  if(!isSale && gh===0 && saleGH>0) gh = saleGH;
  // % giảm luôn tính so với Giá lẻ (không phải so với giá ĐL gốc)
  var pct = function(sale){ return (le>0 && sale>0) ? Math.round((le-sale)/le*100) : 0; };

  var lines = ['GẠCH ĐỒNG TÂM KV23'+(isSale?(isCT2?' – XẢ KHO CT2':' – SALE THÁNG 08 VÀ THÁNG 9'):'')];
  lines.push('📌 Mã: '+p.ma);
  lines.push('📐 Kích cỡ: '+p.kc);
  lines.push('━━━━━━━━━━━━━━');

  if(isSale){
    if(le>0)      lines.push('Giá lẻ: '+f(le));
    if(le>0)      lines.push('');
    if(saleNK>0)  lines.push('Giá ĐL Nhận kho: '+f(saleNK)+(pct(saleNK)>0?' (giảm '+pct(saleNK)+'% so với giá lẻ)':''));
    if(saleGH>0)  lines.push('Giá ĐL Đi giao: '+f(saleGH)+(pct(saleGH)>0?' (giảm '+pct(saleGH)+'% so với giá lẻ)':''));
    if(isCT2 && (vetNK>0 || vetGH>0)){
      lines.push('');
      if(vetNK>0) lines.push('VÉT KHO – Nhận kho: '+f(vetNK)+(pct(vetNK)>0?' (giảm '+pct(vetNK)+'% so với giá lẻ)':''));
      if(vetGH>0) lines.push('VÉT KHO – Đi giao: '+f(vetGH)+(pct(vetGH)>0?' (giảm '+pct(vetGH)+'% so với giá lẻ)':''));
    }
    lines.push('━━━━━━━━━━━━━━');
    lines.push(isCT2?'Xả kho – số lượng có hạn, hết là hết!':'Ưu đãi trong tháng – đặt hàng sớm để giữ giá tốt nhất!');
  } else {
    if(le>0)      lines.push('1. Giá lẻ: '+f(le));
    if(le>0)      lines.push('');
    if(nk>0){
      lines.push('2. Giá đại lý nhận kho: '+f(nk));
    }
    if(nk>0)      lines.push('');
    if(gh>0)      lines.push('3. Giá đại lý đi giao: '+f(gh));
  }

  return lines.join('\n');
}
