function copyText(text){
  // Thử clipboard API trước
  if(navigator.clipboard && window.isSecureContext){
    return navigator.clipboard.writeText(text);
  }
  // Fallback: textarea trick
  return new Promise(function(resolve, reject){
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try{
      var ok = document.execCommand('copy');
      document.body.removeChild(ta);
      if(ok) resolve(); else reject();
    } catch(e){
      document.body.removeChild(ta);
      reject(e);
    }
  });
}

function showZaloChat(msg){
  // Chỉ copy vào clipboard, không mở link, không popup thêm
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(msg).then(function(){
      showToast('✅ Đã copy! Mở Zalo paste vào chat.');
    }).catch(function(){
      fallbackCopy(msg);
    });
  } else {
    fallbackCopy(msg);
  }
}

function fallbackCopy(msg){
  var ta=document.createElement('textarea');
  ta.value=msg;
  ta.style.cssText='position:fixed;top:-9999px;left:-9999px';
  document.body.appendChild(ta);
  ta.select();
  try{
    document.execCommand('copy');
    showToast('✅ Đã copy! Mở Zalo paste vào chat.');
  }catch(e){
    showToast('⚠️ Không copy được, vui lòng copy thủ công.');
  }
  document.body.removeChild(ta);
}
