// ===== QUY ĐỊNH BÁN HÀNG ĐỒNG TÂM =====
// Nguồn: Quy định 2.2 – Đơn vị bán hàng

// Kích cỡ được bán Thùng HOẶC Viên (lẻ)
var KC_THUNG_HOAC_VIEN = {
  // Ceramic
  '400x400':true,'300x600':true,'400x800':true,
  // Porcelain
  '150x600':true,'200x800':true,'200x1200':true,
  '600x600':true,'800x800':true,'1000x1000':true,'600x1200':true
};

// Bảng m²/thùng theo kích cỡ gạch Đồng Tâm (đo thực tế)
var QUY_CACH = {
  // key: "kc|cat" → {vien, m2, day, kg}
  '100x200|ceramic':   {vien:25, m2:0.50,  day:'8',       kg:7.8},
  '150x300|ceramic':   {vien:11, m2:0.495, day:'9',       kg:9.3},
  '150x600|porcelain': {vien:10, m2:0.90,  day:'9.3',     kg:19},
  '200x200|ceramic':   {vien:25, m2:1.00,  day:'16',      kg:null},
  '200x200|porcelain': {vien:12, m2:0.48,  day:'12',      kg:13.48},
  '200x800|porcelain': {vien:10, m2:1.60,  day:'10.5',    kg:37},
  '200x1200|porcelain':{vien:6,  m2:1.44,  day:'11',      kg:null},
  '300x300|porcelain': {vien:11, m2:0.99,  day:'8',       kg:18.6},
  '300x450|ceramic':   {vien:8,  m2:1.08,  day:'-',       kg:null},
  '300x600|ceramic':   {vien:6,  m2:1.08,  day:'8.7',     kg:18},
  '300x600|porcelain': {vien:6,  m2:1.08,  day:'9.2-9.5', kg:24},
  '400x400|porcelain': {vien:6,  m2:0.96,  day:'8.7-9.4', kg:17.4},
  '400x800|porcelain': {vien:4,  m2:1.28,  day:'10.5',    kg:24.5},
  '400x800|ceramic':   {vien:4,  m2:1.28,  day:'10.5',    kg:24.5},
  '600x600|porcelain': {vien:4,  m2:1.44,  day:'9.3-9.5', kg:31.6},
  '600x1200|porcelain':{vien:2,  m2:1.44,  day:'11',      kg:37.4},
  '800x800|porcelain': {vien:3,  m2:1.92,  day:'11',      kg:51},
  '1000x1000|porcelain':{vien:2, m2:2.00,  day:'12.5',    kg:57.1},
};

// Lấy quy cách đúng theo kc + cat (ceramic/porcelain), fallback nếu không có cat
function getQuyCach(kc, cat){
  if(!kc) return null;
  // Chuẩn hóa: X hoa → x thường, bỏ khoảng trắng (Sheet hay gõ nhầm 800X800, 300X600)
  kc = String(kc).trim().replace(/\s+/g,'').replace(/X/g,'x');
  cat = (cat||'').toLowerCase();
  var key = kc+'|'+cat;
  if(QUY_CACH[key]) return QUY_CACH[key];
  // Fallback: thử cat khác nếu chỉ có 1 loại cho kích cỡ đó
  var alt = kc+'|'+(cat==='ceramic'?'porcelain':'ceramic');
  if(QUY_CACH[alt]) return QUY_CACH[alt];
  return null;
}

// Giữ GACH_THUNG (m²/thùng) để tương thích code cũ - build từ QUY_CACH
GACH_THUNG = {};
Object.keys(QUY_CACH).forEach(function(k){
  var kc = k.split('|')[0];
  if(!GACH_THUNG[kc]) GACH_THUNG[kc] = QUY_CACH[k].m2;
});

// Kiểm tra kích cỡ có được bán lẻ viên không
function coTheBanVien(kc){
  if(!kc) return false;
  var m=kc.match(/(\d+)[xX](\d+)/);
  if(!m) return false;
  var key=m[1]+'x'+m[2];
  return !!KC_THUNG_HOAC_VIEN[key];
}

// Tính số thùng và làm tròn theo quy định
function tinhThung(item){
  if(item.loai==='keo') return null;

  // Gạch kính: chỉ bán thùng (6 viên/thùng), đơn vị đã là thùng
  if(item.loai==='kinh'){
    return {
      thung:parseFloat(item.qty)||0,
      thungNguyen:Math.ceil(parseFloat(item.qty)||0),
      m2perThung:null,
      note:'6 viên/thùng',
      chiBanThung:true,
      banVienDuoc:false
    };
  }

  if(item.loai==='ngoi'){
    var p=NGOI.find(function(x){return x.ma===item.ma;});
    if(!p||!p.dong_goi) return null;
    var m=p.dong_goi.match(/(\d+)/);
    if(!m) return null;
    var vienPerThung=parseInt(m[1]);
    if(!vienPerThung) return null;
    var thung=parseFloat(item.qty)/vienPerThung;
    var thungRound=Math.ceil(thung*100)/100;
    return {
      thung:thung,
      thungRound:thungRound,
      m2perThung:null,
      note:p.dong_goi,
      chiBanThung:false, // ngói theo viên
      banVienDuoc:true
    };
  }

  // Gạch
  var kc=item.kc||'';
  var kcMatch=kc.match(/(\d+)[xX](\d+)/);
  if(!kcMatch) return null;
  var kcKey=kcMatch[1]+'x'+kcMatch[2];
  var m2perThung=GACH_THUNG[kcKey];
  if(!m2perThung) return null;

  var qty=parseFloat(item.qty)||0;
  var thungExact=qty/m2perThung;
  var thungRound=Math.ceil(thungExact*100)/100; // làm tròn lên
  var banVienDuoc=!!KC_THUNG_HOAC_VIEN[kcKey];
  var chiBanThung=!banVienDuoc;

  // Nếu chỉ bán thùng: tính m² thực = thùng nguyên × m²/thùng
  var thungNguyen=Math.ceil(thungExact);
  var m2ThucTe=chiBanThung?(thungNguyen*m2perThung):qty;

  return {
    thung:thungExact,
    thungRound:thungRound,
    thungNguyen:thungNguyen,
    m2perThung:m2perThung,
    m2ThucTe:m2ThucTe,
    note:m2perThung.toFixed(2)+' m²/thùng',
    chiBanThung:chiBanThung,
    banVienDuoc:banVienDuoc
  };
}

// Làm tròn m² theo quy định:
// - Chỉ bán thùng → làm tròn lên thùng nguyên
// - Bán được viên → giữ nguyên m² khách nhập
function tinhSoVien(item){
  if(item.loai==='keo'||item.loai==='kinh'||item.loai==='ngoi') return null;
  var qc = getQuyCach(item.kc, item.cat);
  var qty = parseFloat(item.qty)||0;
  // kg/viên chính xác theo mã SAP (lấy từ Sheet) — ưu tiên hơn số kg
  // chung theo nhóm kích cỡ trong QUY_CACH (vốn chỉ là số ước lượng gộp)
  var kgPerVien = kgPerVienCuaMa(item.ma);
  if(qc && qc.m2 > 0){
    var soThung = qty / qc.m2;
    var soVienRaw = soThung * qc.vien;
    var soVien = Math.round(soVienRaw);
    // soVien chỉ THẬT SỰ chính xác khi số m² nhập vào đúng khớp bội số viên -
    // nếu không, Math.round ở trên đã làm tròn (xấp xỉ), phải đánh dấu rõ để
    // UI không hiện dấu "=" cho 1 con số thực ra đã bị làm tròn.
    var soVienExact = Math.abs(soVienRaw-soVien)<1e-6;
    var kg = kgPerVien>0 ? Math.round(soVien*kgPerVien*10)/10
           : (qc.kg ? Math.round(soThung * qc.kg * 10)/10 : null);
    return {soVien:soVien, soVienExact:soVienExact, vienPerThung:qc.vien, kg:kg, kgChinhXac:kgPerVien>0, m2PerThung:qc.m2};
  }
  var kc=item.kc||'';
  var m=kc.match(/(\d+)[xX](\d+)/);
  if(!m) return null;
  var w=parseInt(m[1])/1000, h=parseInt(m[2])/1000;
  if(!w||!h) return null;
  var vienPerM2=1/(w*h);
  var soVienRaw2=qty*vienPerM2;
  var soVien=Math.round(soVienRaw2);
  var soVienExact=Math.abs(soVienRaw2-soVien)<1e-6;
  var kgFallback = kgPerVien>0 ? Math.round(soVien*kgPerVien*10)/10 : null;
  return {soVien:soVien, soVienExact:soVienExact, vienPerM2:Math.round(vienPerM2*10)/10, kg:kgFallback, kgChinhXac:kgPerVien>0};
}

// Hàng CT1/CT2 (có giá Sale) CHỈ được hưởng giá Sale khi lấy đủ thùng
// nguyên - phần dư ra không đủ 1 thùng (viên lẻ) tính theo giá ĐL thường
// (không sale). Chỉ áp dụng với kích cỡ bán được lẻ viên (kích cỡ "chỉ bán
// thùng" thì đã luôn làm tròn lên thùng nguyên từ trước, không bao giờ có
// phần lẻ). Trả về null nếu không cần tách (không phải hàng sale, hoặc mua
// vừa đúng khớp bội số thùng - không có phần lẻ).
function tinhTachGiaSale(item){
  if(item.loai!=='gach' || item.unit!=='m²') return null;
  // Phải dùng cờ CT1/CT2 thật - KHÔNG dùng ns/gs>0 vì gs có fallback = giao
  // thường cho MỌI sản phẩm (kể cả không sale), sẽ nhận nhầm hàng thường
  // thành hàng sale nếu chỉ check ns/gs>0.
  if(item._fromCT!=='CT1' && item._fromCT!=='CT2') return null;
  if(!((item.ns>0)||(item.gs>0))) return null;
  var t=tinhThung(item);
  if(!t || !t.banVienDuoc || !t.m2perThung) return null;
  var m2PerThung=t.m2perThung;
  var qty=parseFloat(item.qty)||0;
  var thungNguyen=Math.floor(qty/m2PerThung+1e-6);
  var m2Sale=Math.round(thungNguyen*m2PerThung*1000)/1000;
  var m2Thuong=Math.round((qty-m2Sale)*1000)/1000;
  if(m2Thuong<=0.001) return null;
  var qc=getQuyCach(item.kc,item.cat);
  var m2PerVien=qc&&qc.vien?m2PerThung/qc.vien:0;
  var vienLe=m2PerVien?Math.round(m2Thuong/m2PerVien):0;
  var vienConThieu=m2PerVien?Math.round((m2PerThung-m2Thuong)/m2PerVien):0;
  var m2ConThieu=Math.round((m2PerThung-m2Thuong)*1000)/1000;
  return {thungNguyen:thungNguyen, m2Sale:m2Sale, m2Thuong:m2Thuong, m2PerThung:m2PerThung,
          vienLe:vienLe, vienConThieu:vienConThieu, m2ConThieu:m2ConThieu};
}

// Bản tổng quát (không phân biệt sale/không sale) - CHỈ tách số lượng ra 2
// phần thùng nguyên + viên lẻ, dùng cho việc XUẤT CHỨNG TỪ (Excel/PDF) cần
// liệt kê rõ "mua bao nhiêu thùng, bao nhiêu viên lẻ" trên 2 dòng riêng theo
// đúng mẫu báo giá thật - áp dụng cho MỌI sản phẩm gạch bán được lẻ viên,
// không chỉ hàng CT1/CT2. Việc tính GIÁ cho từng dòng xử lý riêng ở nơi gọi.
function tinhTachThungVien(item){
  if(item.loai!=='gach' || item.unit!=='m²') return null;
  var t=tinhThung(item);
  if(!t || !t.banVienDuoc || !t.m2perThung) return null;
  var qc=getQuyCach(item.kc,item.cat);
  if(!qc || !qc.vien) return null;
  var m2PerThung=t.m2perThung;
  var qty=parseFloat(item.qty)||0;
  var thungNguyen=Math.floor(qty/m2PerThung+1e-6);
  var m2Thung=Math.round(thungNguyen*m2PerThung*1000)/1000;
  var m2Vien=Math.round((qty-m2Thung)*1000)/1000;
  if(m2Vien<=0.001) return null; // đủ thùng tròn, không cần tách dòng
  var m2PerVien=m2PerThung/qc.vien;
  var vienLe=Math.round(m2Vien/m2PerVien);
  return {thungNguyen:thungNguyen, m2Thung:m2Thung, m2Vien:m2Vien, vienLe:vienLe,
          m2PerThung:m2PerThung, m2PerVien:m2PerVien};
}

function laTronQtyTheoQuyDinh(item){
  var t=tinhThung(item);
  if(!t||t.banVienDuoc) return parseFloat(item.qty)||0;
  // Chỉ bán thùng: qty phải là bội số của m²/thùng
  return t.m2ThucTe;
}


function addToDon(ma, qty){
  if(!ma) return;
  if(!checkSession()){ showToast('🔐 Đăng nhập để đặt hàng & xem giá đại lý'); return; }
  qty = qty || 1;
  var p = DATA.find(function(x){return x.ma===ma;});
  if(!p) return;
  var exist = donItems.find(function(x){return x.ma===ma;});
  if(exist){ exist.qty = Math.round((exist.qty+qty)*100)/100; }
  else {
    donItems.push({
      ma:p.ma, ten:p.tenHD||p.ten||p.ma, kc:p.kc, cat:p.cat, unit:'m²', loai:'gach',
      le:p.le||0,
      nhan:p.nhan||0,   // giá nhận kho
      giao:p.giao||0,   // giá đi giao
      ns:p.ns||0,       // giá nhận sale
      gs:p.gs||0,       // giá giao sale
      // Cờ CT1/CT2 thật (khác ns/gs>0 vì gs có fallback = giao cho MỌI sản
      // phẩm kể cả không sale - phải dùng cờ này mới biết đúng hàng nào thật
      // sự đang sale, ví dụ để tách giá Sale/thường khi mua lẻ không đủ thùng).
      _fromCT:p._fromCT||null,
      qty:qty
    });
  }
  updateDonBadge();
  showToast('✓ Đã thêm vào đơn!');
}

// ===== Toggle đơn vị nhập trong popup chi tiết: m² hoặc thùng =====
var dpUnit = 'm2'; // 'm2' hoặc 'thung'

function setDpUnit(u){
  dpUnit = u;
  var bM2=document.getElementById('dp-unit-m2'), bThung=document.getElementById('dp-unit-thung');
  var label=document.getElementById('dp-qty-unit-label');
  if(u==='m2'){
    bM2.style.background='var(--red)'; bM2.style.color='#fff'; bM2.style.border='none';
    bThung.style.background='var(--bg1)'; bThung.style.color='var(--t2)'; bThung.style.border='1.5px solid var(--bd)';
    label.textContent='m²';
  } else {
    bThung.style.background='var(--red)'; bThung.style.color='#fff'; bThung.style.border='none';
    bM2.style.background='var(--bg1)'; bM2.style.color='var(--t2)'; bM2.style.border='1.5px solid var(--bd)';
    label.textContent='thùng';
  }
  // Reset về 1 khi đổi đơn vị
  document.getElementById('dp-qty-input').value = 1;
  calcDpQty();
}

// Nút +/- trong popup chi tiết SP - LUÔN làm tròn về đúng mốc viên/thùng gần
// nhất TRƯỚC rồi mới nhích 1 bước, chứ không cộng thẳng vào số đang gõ dở
// (số đang gõ có thể lệch khỏi mốc viên) - đảm bảo bấm xong luôn là số m²
// tròn viên tuyệt đối (m²) hoặc số thùng nguyên (thùng), không còn số lẻ.
function stepDpQty(dir){
  var p = DATA.find(function(x){return x.ma===curP_ma;});
  var inp = document.getElementById('dp-qty-input');
  if(!p || !inp) return;
  var cur = Math.max(0, parseVN(inp.value)||0);
  var qc = getQuyCach(p.kc, p.cat);
  var next;
  if(dpUnit==='m2' && qc && qc.m2 && qc.vien){
    var step = qc.m2/qc.vien;
    var vienCur = Math.round(cur/step);
    next = Math.max(1, vienCur+dir)*step;
  } else {
    next = Math.max(1, Math.round(cur)+dir);
  }
  next = Math.round(next*1000)/1000;
  inp.value = next;
  calcDpQty();
}

function calcDpQty(){
  var p = DATA.find(function(x){return x.ma===curP_ma;});
  if(!p) return;
  var val = parseVN(document.getElementById('dp-qty-input').value);
  var qc = getQuyCach(p.kc, p.cat);
  var convertEl = document.getElementById('dp-qty-convert');
  var snapEl = document.getElementById('dp-qty-snap');
  if(!qc || !qc.m2){ convertEl.textContent=''; if(snapEl) snapEl.style.display='none'; return; }

  // "=" khi con số là đúng phép nhân/chia (thùng, kg, m²) - "≈" CHỈ khi số
  // viên bị làm tròn thật sự (input không khớp đúng bội số viên vật lý).
  function isInt(n){ return Math.abs(n-Math.round(n))<1e-6; }
  if(dpUnit==='thung'){
    var m2=Math.round(val*qc.m2*100)/100;
    var vienRaw=val*qc.vien, vienExact=isInt(vienRaw), vien=Math.round(vienRaw);
    var kgV=qc.kg?Math.round(val*qc.kg*10)/10:0;
    convertEl.innerHTML='= <b>'+m2+'</b> m²'+(vien?' · '+(vienExact?'=':'≈')+' <b>'+vien+'</b> viên':'')+(kgV?' · <b>'+kgV+'</b> kg':'');
    if(snapEl) snapEl.style.display='none';
  } else {
    var thung=Math.round((val/qc.m2)*100)/100, thungN=Math.ceil(val/qc.m2);
    var vienRawT=qc.vien?val/qc.m2*qc.vien:0, vienExactT=isInt(vienRawT), vienT=Math.round(vienRawT);
    var kgT=qc.kg?Math.round(val/qc.m2*qc.kg*10)/10:0;
    var lamTron=thungN!==thung?' (làm tròn: <b>'+thungN+'</b> thùng)':'';
    convertEl.innerHTML='= <b>'+thung+'</b> thùng'+lamTron
      +(vienT?'<br>'+(vienExactT?'=':'≈')+' <b>'+vienT+'</b> viên':'')+(kgT?' · <b>'+kgT+'</b> kg':'');
    renderDpQtySnap(val, qc, snapEl);
  }
}

// Gạch chỉ bán được theo viên/thùng nguyên (không xuất kho được số m² lẻ),
// nên khi khách/nhân viên gõ tay 1 số m² tuỳ ý, hiện sẵn 2 lựa chọn làm tròn
// gần nhất (xuống/lên đúng 1 viên) để bấm chọn nhanh, khỏi tự tính tay.
function renderDpQtySnap(val, qc, snapEl){
  if(!snapEl || !qc.vien) { if(snapEl) snapEl.style.display='none'; return; }
  var m2PerVien = qc.m2/qc.vien;
  var vienExact = val/m2PerVien;
  var vienDown = Math.floor(vienExact+1e-6);
  if(vienDown<0) vienDown=0;
  var vienUp = vienDown+1;
  // Nếu số đang gõ đã đúng khớp 1 số nguyên viên rồi thì khỏi cần gợi ý
  if(Math.abs(vienExact-vienDown)<1e-6){ snapEl.style.display='none'; return; }
  function label(vienTong){
    var m2=Math.round(vienTong*m2PerVien*100)/100;
    var thungN=Math.floor(vienTong/qc.vien), vienDu=vienTong-thungN*qc.vien;
    var thungStr=thungN+' thùng'+(vienDu>0?' + '+vienDu+' viên':'');
    return {m2:m2, text:thungStr+' — '+m2+' m²'};
  }
  var down=label(vienDown), up=label(vienUp);
  snapEl.style.display='flex';
  snapEl.innerHTML=
    '<button type="button" onclick="_snapDpQty('+down.m2+')" style="flex:1;padding:8px 6px;border-radius:8px;border:1.5px solid var(--bd2);background:var(--bg2);color:var(--t1);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--f)">↓ Làm tròn xuống<br>'+down.text+'</button>'
    +'<button type="button" onclick="_snapDpQty('+up.m2+')" style="flex:1;padding:8px 6px;border-radius:8px;border:1.5px solid var(--bd2);background:var(--bg2);color:var(--t1);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--f)">↑ Làm tròn lên<br>'+up.text+'</button>';
}
function _snapDpQty(m2){
  document.getElementById('dp-qty-input').value=m2;
  calcDpQty();
}

// Tính số thùng cần mua từ kích thước phòng (dài x rộng) — hữu ích khi tư
// vấn khách lát nguyên 1 phòng, tự điền luôn vào ô số lượng để thêm vào đơn.
function tinhTheoDienTichPhong(){
  var p = DATA.find(function(x){return x.ma===curP_ma;});
  if(!p) return;
  var dai=parseVN(document.getElementById('dp-room-dai').value);
  var rong=parseVN(document.getElementById('dp-room-rong').value);
  var resultEl=document.getElementById('dp-room-result');
  if(dai<=0||rong<=0){ resultEl.textContent='Vui lòng nhập đủ chiều dài và chiều rộng!'; resultEl.style.color='#C0232A'; return; }

  var m2=Math.round(dai*rong*100)/100;
  var qc=getQuyCach(p.kc,p.cat);
  resultEl.style.color='#0D47A1';
  if(qc && qc.m2>0){
    var thungN=Math.ceil(m2/qc.m2);
    var m2Thuc=Math.round(thungN*qc.m2*100)/100;
    var haoHut=Math.round((m2Thuc-m2)*100)/100;
    resultEl.innerHTML='Diện tích phòng: <b>'+m2+'</b> m² → cần mua <b>'+thungN+'</b> thùng (≈ '+m2Thuc+' m²'
      +(haoHut>0?', dư '+haoHut+' m² để cắt/bù hao hụt':'')+')';
    // Tự điền vào ô số lượng theo thùng để thêm vào đơn cho đúng số thùng nguyên
    setDpUnit('thung');
    document.getElementById('dp-qty-input').value=thungN;
    calcDpQty();
  } else {
    resultEl.innerHTML='Diện tích phòng: <b>'+m2+'</b> m²';
    setDpUnit('m2');
    document.getElementById('dp-qty-input').value=m2;
    calcDpQty();
  }
}

function addToDonWithQty(){
  var p = DATA.find(function(x){return x.ma===curP_ma;});
  if(!p) return;
  var val = parseVN(document.getElementById('dp-qty-input').value);
  if(val<=0){ alert('Vui lòng nhập số lượng!'); return; }

  var qc = getQuyCach(p.kc, p.cat);
  var qtyM2;

  if(dpUnit==='thung' && qc && qc.m2){
    // Nhập theo thùng → đổi sang m² để lưu (đơn vị chuẩn trong giỏ hàng)
    qtyM2 = Math.round(val * qc.m2 * 100)/100;
  } else {
    qtyM2 = val;
    // Nếu kích cỡ chỉ bán thùng → làm tròn lên thùng nguyên
    if(qc && qc.m2){
      var isThungHoacVien = coTheBanVien(p.kc);
      if(!isThungHoacVien){
        var thungNguyen = Math.ceil(val/qc.m2);
        qtyM2 = Math.round(thungNguyen * qc.m2 * 100)/100;
      }
    }
  }

  addToDon(curP_ma, qtyM2);
  // Reset input
  document.getElementById('dp-qty-input').value = 1;
  setDpUnit('m2');
  // Đóng detail panel sau khi thêm vào đơn
  closeDp();
}

