function showToast(msg,type){
  // Xóa toast cũ cùng loại nếu còn
  var old=document.querySelector('.dt-toast');
  if(old) old.remove();
  var isErr=type==='error', isWarn=type==='warn';
  var bg=isErr?'#C62828':isWarn?'#E65100':'#1B8A3C';
  var t=document.createElement('div');
  t.className='dt-toast';
  t.textContent=msg;
  t.style.cssText='position:fixed;bottom:88px;left:50%;transform:translateX(-50%) translateY(8px);background:'+bg+';color:#fff;padding:10px 22px;border-radius:24px;font-size:13px;font-weight:600;z-index:9999;white-space:nowrap;box-shadow:0 4px 16px rgba(0,0,0,.22);opacity:0;transition:opacity .2s ease,transform .2s ease;pointer-events:none';
  document.body.appendChild(t);
  requestAnimationFrame(function(){
    t.style.opacity='1';
    t.style.transform='translateX(-50%) translateY(0)';
  });
  setTimeout(function(){
    t.style.opacity='0';
    t.style.transform='translateX(-50%) translateY(8px)';
    setTimeout(function(){t.remove();},220);
  },2200);
}

function updateDonBadge(){
  var badge=document.getElementById('don-badge');
  var spCount=donItems.length;
  if(badge){badge.textContent=spCount;badge.style.display=spCount>0?'inline-flex':'none';}
  // Side-nav badge (desktop)
  var snBadge=document.getElementById('sn-don-badge');
  if(snBadge){
    snBadge.textContent=spCount>9?'9+':spCount;
    snBadge.classList.toggle('show',spCount>0);
  }
  // Topbar cart label (mobile)
  var label=document.getElementById('don-cart-label');
  if(label){
    if(spCount===0){
      label.textContent='Giỏ hàng';
    } else {
      // Gộp số lượng theo đúng đơn vị của từng dòng (m², bao, tấm...) thay vì
      // cộng thẳng mọi đơn vị lại rồi gán nhãn "cái" - vừa sai vừa gây nhầm lẫn
      var byUnit={};
      donItems.forEach(function(x){
        var u=x.unit||'m²';
        byUnit[u]=(byUnit[u]||0)+x.qty;
      });
      var qtyText=Object.keys(byUnit).map(function(u){
        var n=Math.round(byUnit[u]*100)/100;
        return n.toLocaleString('vi-VN')+' '+u;
      }).join(' · ');
      label.textContent=spCount+' SP · '+qtyText;
    }
  }
  saveDonItemsToStorage();
}

// Lưu giỏ hàng vào localStorage để không mất khi refresh/đóng tab giữa lúc tư vấn khách
var DON_STORAGE_KEY='dt_don_items';
function saveDonItemsToStorage(){
  try{ localStorage.setItem(DON_STORAGE_KEY, JSON.stringify(donItems)); }catch(e){}
}
function loadDonItemsFromStorage(){
  try{
    var raw=localStorage.getItem(DON_STORAGE_KEY);
    if(raw){
      var arr=JSON.parse(raw);
      if(Array.isArray(arr)) donItems=arr;
    }
  }catch(e){}
}

function renderDon(){
  var isEmpty=donItems.length===0;
  document.getElementById('don-empty').style.display=isEmpty?'block':'none';
  document.getElementById('don-content').style.display=isEmpty?'none':'block';
  if(isEmpty) return;
  var el=document.getElementById('don-list'); el.innerHTML='';
  donItems.forEach(function(item){
    var unit=item.unit||'m²';
    var loai=item.loai||'gach';
    var nhanVal, giaoVal;
    var qty_=parseFloat(item.qty)||0;
    if(item.loai==='kinh'){
      // Gạch kính: 3 mức theo số thùng
      if(qty_>=50){ nhanVal=item.nhan3||item.nhan; giaoVal=item.giao3||item.giao; }
      else if(qty_>=21){ nhanVal=item.nhan2||item.nhan; giaoVal=item.giao2||item.giao; }
      else { nhanVal=item.nhan; giaoVal=item.giao; }
    } else if(item.loai==='keo'){
      // Keo/Bột: 2 mức (< 50 bao hoặc ≥ 50 bao)
      if(qty_>=50){ nhanVal=item.nhan2||item.nhan; giaoVal=item.giao2||item.giao; }
      else { nhanVal=item.nhan; giaoVal=item.giao; }
    } else {
      // Gạch / Ngói: dùng giá sale nếu có
      nhanVal=item.ns>0?item.ns:item.nhan;
      giaoVal=item.gs>0?item.gs:item.giao;
    }

    var div=document.createElement('div'); div.className='cart-item';
    var label = loai==='ngoi'?'🏠 Ngói': loai==='keo'?'🧱 Keo': loai==='kinh'?'💎 Kính':'🏗️ Gạch';
    div.innerHTML=
      '<div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:6px">'
      +'<div>'
      +'<p style="font-size:12px;color:var(--t2);margin-bottom:1px">'+label+'</p>'
      +'<p style="font-size:13px;font-weight:700;margin-bottom:2px">'+(item.ten||item.ma)+'</p>'
      +'<p style="font-size:11px;color:var(--t2)">'+item.ma+(item.kc&&item.kc!=='–'?' · '+item.kc:'')+'</p>'
      +(item.ns>0?'<span style="font-size:10px;background:#FDECEA;color:#8B0000;padding:1px 6px;border-radius:4px;font-weight:600">🔥 SALE</span>':'')
      +'</div>'
      +'<button data-rm="'+item.ma+'" style="color:var(--t3);border:none;background:transparent;font-size:18px;cursor:pointer;flex-shrink:0">✕</button>'
      +'</div>'
      +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px">'
      +'<button data-qty="'+item.ma+'" data-d="-1" class="qty-btn" style="flex-shrink:0">−</button>'
      +'<input type="text" inputmode="decimal" data-inp="'+item.ma+'" value="'+item.qty+'" '
        +'style="width:72px;text-align:center;font-size:14px;font-weight:700;padding:4px 6px;'
        +'border:1.5px solid var(--bd2);border-radius:6px;background:var(--bg1);'
        +'font-family:var(--f);-moz-appearance:textfield;" />'
      +'<button data-qty="'+item.ma+'" data-d="1" class="qty-btn" style="flex-shrink:0">+</button>'
      +'<span style="font-size:11px;color:var(--t2)">'+unit+'</span>'
      +(function(){
        var t=tinhThung(item);
        if(!t) return '';
        var out='';
        if(item.loai==='kinh'){
          // Gạch kính: đơn vị thùng, chỉ hiện tổng thùng
          out+='<span style="font-size:11px;color:#0D47A1;margin-left:8px">💎 '+t.thungNguyen+' thùng (6 viên/thùng)</span>';
        } else if(t.chiBanThung){
          // Chỉ bán thùng — cảnh báo + m² làm tròn
          out+='<span style="font-size:10px;background:#FFF3E0;color:#E65100;padding:1px 6px;border-radius:4px;font-weight:700;margin-left:6px">⚠️ Chỉ xuất thùng</span>';
          out+='<br><span style="font-size:11px;color:#0D47A1">→ '+t.thungNguyen+' thùng × '+(t.m2perThung||0)+' m²/thùng = '+((t.m2ThucTe||0).toFixed(2))+' m²</span>';
        } else {
          var thungStr=Math.round(t.thung*100)/100;
          var thungDisp=thungStr%1===0?thungStr.toString():thungStr.toFixed(2);
          // Số thùng là phép chia đúng (m² ÷ m²/thùng) - không phải làm tròn
          // vật lý như viên, nên luôn hiện dấu "=" chứ không phải "≈".
          out+='<span style="font-size:11px;color:#0D47A1;margin-left:8px">= '+thungDisp+' thùng ('+t.note+')</span>';
        }
        return out;
      })()
      +(function(){
        if(item.loai==='keo'||item.loai==='kinh'||item.loai==='ngoi') return '';
        var v=tinhSoVien(item);
        if(!v||!v.soVien) return '';
        // Chỉ hiện "≈" khi số m² nhập KHÔNG khớp đúng bội số viên (viên thật
        // sự bị làm tròn) - còn lại (khớp đúng viên) hiện "=" cho đúng bản chất.
        var s='<span style="font-size:11px;color:var(--t2);margin-left:8px">'+(v.soVienExact?'=':'≈')+' '+v.soVien+' viên';
        if(v.kg) s+=' · '+v.kg+'kg';
        s+='</span>';
        return s;
      })()
      +'</div>'
      // Bảng giá 3 hàng (hoặc tách 2 phần Sale/Thường nếu mua lẻ không đủ thùng)
      +'<div style="background:var(--bg2);border-radius:var(--r8);padding:8px 10px;font-size:12px">'
      +'<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:0.5px solid var(--bd)">'
      +'<span style="color:var(--t2)">Giá lẻ (KH)</span>'
      +'<span style="font-weight:600">'+(item.le>0?item.le.toLocaleString('vi-VN')+'đ/'+unit+' → '+(item.le*item.qty).toLocaleString('vi-VN')+'đ':'Liên hệ')+'</span>'
      +'</div>'
      +(function(){
        var split=tinhTachGiaSale(item);
        if(!split){
          return '<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:0.5px solid var(--bd)">'
            +'<span style="color:#1B5E20">Giá ĐL nhận kho</span>'
            +'<span style="font-weight:700;color:#1B5E20">'+(nhanVal>0?nhanVal.toLocaleString('vi-VN')+'đ/'+unit+' → '+(nhanVal*item.qty).toLocaleString('vi-VN')+'đ':'–')+'</span>'
            +'</div>'
            +'<div style="display:flex;justify-content:space-between;padding:3px 0">'
            +'<span style="color:#0D47A1">Giá ĐL đi giao</span>'
            +'<span style="font-weight:700;color:#0D47A1">'+(giaoVal>0?giaoVal.toLocaleString('vi-VN')+'đ/'+unit+' → '+(giaoVal*item.qty).toLocaleString('vi-VN')+'đ':'–')+'</span>'
            +'</div>';
        }
        var giaTinh=curGiaoHang==='nhan'?(item.nhan||0):(item.giao||0);
        var giaSale=curGiaoHang==='nhan'?(item.ns||item.nhan||0):(item.gs||item.giao||0);
        var tienSale=giaSale*split.m2Sale, tienThuong=giaTinh*split.m2Thuong;
        return '<div style="padding:5px 0;border-bottom:0.5px dashed var(--bd)">'
          +'<div style="display:flex;justify-content:space-between;font-size:11px">'
          +'<span style="color:#C0232A">🔥 Sale: '+split.thungNguyen+' thùng ('+split.m2Sale+'m²) × '+giaSale.toLocaleString('vi-VN')+'đ</span>'
          +'<span style="font-weight:700;color:#C0232A">'+Math.round(tienSale).toLocaleString('vi-VN')+'đ</span></div>'
          +'<div style="display:flex;justify-content:space-between;font-size:11px;margin-top:2px">'
          +'<span style="color:var(--t2)">Giá thường: '+split.vienLe+' viên lẻ ('+split.m2Thuong+'m²) × '+giaTinh.toLocaleString('vi-VN')+'đ</span>'
          +'<span style="font-weight:700;color:var(--t1)">'+Math.round(tienThuong).toLocaleString('vi-VN')+'đ</span></div>'
          +'<div style="font-size:10px;color:#0D47A1;margin-top:3px">💡 Mua thêm '+split.vienConThieu+' viên nữa ('+split.m2ConThieu+'m²) để đủ thùng — được giá Sale toàn bộ</div>'
          +'</div>';
      })()
      +'</div>';
    el.appendChild(div);
  });

  // Event delegation
  el.onclick=function(e){
    var rm=e.target.closest('[data-rm]');
    if(rm){removeDon(rm.dataset.rm);return;}
    var qb=e.target.closest('[data-qty]');
    if(qb){
      var ma=qb.dataset.qty;
      var item=donItems.find(function(x){return x.ma===ma;});
      var inp=el.querySelector('input[data-inp="'+ma+'"]');
      var cur=inp?Math.max(0.01,parseVN(inp.value)||1):1;
      var d=parseInt(qb.dataset.d);
      var next;
      // Gạch tính theo m²: LUÔN làm tròn về đúng mốc viên gần nhất TRƯỚC rồi
      // mới nhích 1 viên - không cộng thẳng vào số đang gõ dở (có thể đang
      // lệch khỏi mốc viên) - đảm bảo bấm xong luôn là số m² tròn viên tuyệt đối.
      if(item && item.loai==='gach' && item.unit==='m²'){
        var qc=getQuyCach(item.kc,item.cat);
        if(qc && qc.m2 && qc.vien){
          var step=qc.m2/qc.vien;
          var vienCur=Math.round(cur/step);
          next=Math.max(1,vienCur+d)*step;
        }
      }
      if(next===undefined) next=Math.max(0.01,cur+d);
      next=Math.round(next*1000)/1000;
      if(inp) inp.value=next;
      setDonQty(ma,next);   // cập nhật donItems.qty → calcAndShowTotals
      return;
    }
  };
  el.oninput=function(e){
    var inp=e.target.closest('[data-inp]');
    if(!inp) return;
    var val=parseVN(inp.value);
    if(val>0){
      setDonQty(inp.dataset.inp, val);
    }
  };

  calcAndShowTotals();
}

function updateDonQty(ma,d){
  var item=donItems.find(function(x){return x.ma===ma;});
  if(!item) return;
  item.qty=Math.max(1,item.qty+d);
  updateDonBadge(); renderDon();
}
function setDonQty(ma,val){
  var item=donItems.find(function(x){return x.ma===ma;});
  if(!item) return;
  // Làm tròn tới 3 chữ số thập phân (không phải 2) - vài kích cỡ gạch có
  // m²/viên lẻ tới 3 số (vd 0.045m²) nên làm tròn 2 số sẽ làm sai lệch số viên.
  val=Math.round((parseVN(val)||0.01)*1000)/1000;
  if(val<0.01) val=0.01;

  // Gạch kính: chỉ bán nguyên thùng → làm tròn lên số nguyên
  if(item.loai==='kinh'){
    val=Math.max(1, Math.round(val));
  }
  // Gạch thường: nếu kích cỡ chỉ bán thùng → làm tròn lên thùng nguyên
  else if(item.loai!=='keo'&&item.loai!=='ngoi'){
    var t=tinhThung({ma:item.ma,kc:item.kc,loai:item.loai,qty:val});
    if(t && t.chiBanThung && t.m2ThucTe){
      val=t.m2ThucTe;
    }
  }

  // Cập nhật ô input
  var inp=document.querySelector('input[data-inp="'+ma+'"]');
  if(inp) inp.value=val;

  item.qty=val;
  updateDonBadge();
  renderDon();
}
function removeDon(ma){donItems=donItems.filter(function(x){return x.ma!==ma;});updateDonBadge();renderDon();}
function guiDonHang(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  if(donItems.length===0){alert('Chưa có sản phẩm trong đơn!');return;}
  var ten=document.getElementById('don-ten').value.trim();
  var sdt=document.getElementById('don-sdt').value.trim();
  if(!ten){alert('Vui lòng nhập tên khách hàng!');document.getElementById('don-ten').focus();return;}
  if(!sdt){alert('Vui lòng nhập số điện thoại!');document.getElementById('don-sdt').focus();return;}

  document.getElementById('btn-gui-don').style.display='none';
  document.getElementById('gui-don-status').style.display='block';
  document.getElementById('gui-don-ok').style.display='none';

  // Lấy thông tin user đang đăng nhập
  var sess=checkSession();
  var nguoiLap=sess?sess.name:'Sales Tool';

  var orderData={
    id:'DH'+Date.now(),
    ten:ten,
    sdt:sdt,
    diachi:document.getElementById('don-dc').value.trim(),
    ghichu:document.getElementById('don-note').value.trim()+
      (document.getElementById('don-cty').value.trim()?' | Cty: '+document.getElementById('don-cty').value.trim():''),
    ngay:new Date().toLocaleString('vi-VN'),
    nguoi_lap:nguoiLap,
    giao_hang:curGiaoHang==='nhan'?'Nhận tại kho':'Giao tận nơi',
    items:donItems.map(function(c){
      var nhanVal=c.ns>0?c.ns:c.nhan;
      var giaoVal=c.gs>0?c.gs:c.giao;
      return {
        ma:c.ma,
        ten_sp:c.ten||c.ma,
        kc:c.kc||'–',
        unit:c.unit||'m²',
        so_luong:c.qty,
        gia_le:c.le||0,
        gia_nhan:nhanVal||0,
        gia_giao:giaoVal||0
      };
    })
  };

  var encoded=encodeURIComponent(JSON.stringify(orderData));
  var cbName='_cb_luuDon_'+Date.now();
  var s=document.createElement('script');
  var done=false;
  function ketThucGuiDon(thanhCong){
    if(done) return; done=true;
    if(s.parentNode) s.parentNode.removeChild(s);
    delete window[cbName];
    document.getElementById('gui-don-status').style.display='none';
    if(thanhCong){
      document.getElementById('gui-don-ok').style.display='block';
      document.getElementById('btn-gui-don').style.display='none';
      fetchKhachHangFromSheet(); // nạp lại danh sách khách (vừa thêm khách mới)
    } else {
      document.getElementById('btn-gui-don').style.display='block';
      alert('❌ Gửi đơn không thành công, vui lòng thử lại! (Kiểm tra mạng / Apps Script URL)');
    }
  }
  window[cbName]=function(res){
    ketThucGuiDon(res && res.status==='ok');
  };
  var t=setTimeout(function(){ ketThucGuiDon(false); },15000);
  // Gọi Apps Script qua JSONP để biết chắc đơn đã lưu thành công, thay vì
  // no-cors (không đọc được response → trước đây luôn báo "thành công" dù
  // request có thể đã lỗi action).
  var url=APPS_URL+'?action=luuDon&data='+encoded+'&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(authTok())+'&callback='+encodeURIComponent(cbName);
  s.src=url;
  s.onerror=function(){ clearTimeout(t); ketThucGuiDon(false); };
  document.head.appendChild(s);
}

// ===== MINI-CRM: KHÁCH HÀNG (autocomplete) =====
var khachHangList=[];
function fetchKhachHangFromSheet(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  var cbName='_onKhachHang';
  window[cbName]=function(res){
    if(res && res.status==='ok' && res.data){
      khachHangList=res.data;
      var lTen=document.getElementById('kh-list-ten');
      var lSdt=document.getElementById('kh-list-sdt');
      if(lTen) lTen.innerHTML=khachHangList.map(function(k){return '<option value="'+(k.ten||'').replace(/"/g,'')+'">';}).join('');
      if(lSdt) lSdt.innerHTML=khachHangList.map(function(k){return '<option value="'+(k.sdt||'').replace(/"/g,'')+'">';}).join('');
    }
    var s=document.getElementById('_kh_script');
    if(s) s.remove();
  };
  var old=document.getElementById('_kh_script');
  if(old) old.remove();
  var s=document.createElement('script');
  s.id='_kh_script';
  s.src=APPS_URL+'?action=getKhachHang&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(authTok())+'&callback='+cbName;
  s.onerror=function(){ s.remove(); };
  document.head.appendChild(s);
}
// Khi nhân viên chọn 1 khách có sẵn (tên hoặc SĐT khớp) → tự điền các ô còn lại
function onChonKhachHang(){
  var ten=document.getElementById('don-ten').value.trim();
  var sdt=document.getElementById('don-sdt').value.trim();
  var found=khachHangList.find(function(k){return k.sdt===sdt || (ten && k.ten===ten);});
  if(found){
    if(!ten && found.ten) document.getElementById('don-ten').value=found.ten;
    if(!sdt && found.sdt) document.getElementById('don-sdt').value=found.sdt;
    var dc=document.getElementById('don-dc');
    if(dc && !dc.value.trim() && found.diachi) dc.value=found.diachi;
  }
}

// ===== TỒN KHO CHI TIẾT THEO KHO + SỐ LÔ =====
var tonKhoChiTiet={};
var tonKhoLoaded=false;
var _tkModalMa=null, _tkModalTen=null;
var TEN_TIER={nhanh:'🟢 Có hàng ngay',mai:'🟡 Hôm nay chuyển – mai có hàng',cho15:'🔴 Chờ 15 ngày'};
var TK_CACHE_KEY='dt_tk_v1', TK_CACHE_TTL=30*60*1000;
function tkLoadingBanner(show){
  var el=document.getElementById('tk-loading-bar');
  if(!el) return;
  el.style.display=show?'flex':'none';
}
function fetchTonKhoChiTiet(){
  var APPS_URL='https://script.google.com/macros/s/AKfycbyrO8symCYOkWsGG0nRWPF7gpndC3mzEVUk15UvWrA0O81ZUumW-kX_gEOZhtCJ34bMVQ/exec';
  // Hiện loading indicator
  tkLoadingBanner(true);
  // Load cache ngay lập tức nếu còn hiệu lực
  try{
    var cached=JSON.parse(localStorage.getItem(TK_CACHE_KEY)||'{}');
    if(cached.ts && cached.data && (Date.now()-cached.ts)<TK_CACHE_TTL){
      tonKhoChiTiet=cached.data;
      tonKhoLoaded=true;
      tkLoadingBanner(false);
      if(typeof render==='function') render();
      if(typeof renderSale==='function') renderSale();
      _refreshTonKhoModalIfOpen();
    }
  }catch(e){}
  // Vẫn fetch GAS để cập nhật mới nhất (chạy nền)
  var cbName='_onTonKhoChiTiet';
  window[cbName]=function(res){
    if(res && res.status==='ok' && res.data){
      tonKhoChiTiet=res.data;
      try{ localStorage.setItem(TK_CACHE_KEY,JSON.stringify({ts:Date.now(),data:res.data})); }catch(e){}
      tkLoadingBanner(false);
      if(typeof render==='function') render();
      if(typeof renderSale==='function') renderSale();
    }
    tonKhoLoaded=true;
    _refreshTonKhoModalIfOpen();
    var s=document.getElementById('_tkct_script');
    if(s) s.remove();
  };
  var old=document.getElementById('_tkct_script');
  if(old) old.remove();
  var s=document.createElement('script');
  s.id='_tkct_script';
  s.src=APPS_URL+'?action=getTonKhoChiTiet&k='+encodeURIComponent(APP_KEY)+'&t='+encodeURIComponent(authTok())+'&callback='+cbName;
  s.onerror=function(){ tkLoadingBanner(false); s.remove(); };
  document.head.appendChild(s);
}

