    +'<input type="text" id="qltk-username" placeholder="Username (vd: anhA_q7)" style="font-size:13px"/>'
    +'<input type="text" id="qltk-name" placeholder="Tên hiển thị (vd: Anh A - Quận 7)" style="font-size:13px"/>'
    +'<input type="text" id="qltk-password" placeholder="Mật khẩu (để trống nếu không đổi)" style="font-size:13px"/>'
    +'<select id="qltk-role" style="font-size:13px;padding:11px;border:1.5px solid var(--bd2);border-radius:var(--r);background:var(--bg1);font-family:var(--f)">'
    +'<option value="" selected disabled>-- Chọn loại tài khoản --</option>'
    +'<option value="khachhang">Khách hàng / Đại lý</option>'
    +'<option value="nv">Nhân viên</option>'
    +'<option value="admin">Admin</option>'
    +'</select>'
    +'<button onclick="luuTaiKhoan()" style="padding:11px;border:none;border-radius:var(--r8);background:#0D47A1;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:var(--f)">💾 Lưu tài khoản</button>'
    +'<p id="qltk-msg" style="font-size:12px;text-align:center;margin-top:4px"></p>'
    +'</div>'
    +'</div>';
