      +'<td class="ma">'+(item.ten&&item.ten!==item.ma?item.ten:item.ma)+(item.ten&&item.ten!==item.ma?'<br><span class="sub">'+item.ma+'</span>':'')+'</td>'
      +'<td class="tc">'+(item.kc&&item.kc!=='–'?item.kc:'–')+'</td>'
