    +'.lbl{font-size:9pt;color:#888;padding-right:10px;white-space:nowrap}'
    +'.val{font-size:9.5pt;font-weight:600;color:#111}'
    +'.th{background:#f5f5f5;color:#333;font-size:9pt;font-weight:bold;text-align:center;padding:6px;border:1px solid #ddd;border-bottom:2px solid #C0232A}'
    +'.td{font-size:9.5pt;border:1px solid #eee;padding:5px 6px;vertical-align:middle}'
