(function(){
  function measure(){
    var tb=document.querySelector('.topbar');
    var tbH=tb?Math.round(tb.getBoundingClientRect().height):56;
    var head=document.getElementById('tra-head');
    var hH=head?Math.round(head.getBoundingClientRect().height):0;
    var r=document.documentElement.style;
    r.setProperty('--tbH', tbH+'px');
    r.setProperty('--headBottom', (tbH+hH)+'px');
    var sHead=document.getElementById('sale-head');
    if(sHead){ var shH=Math.round(sHead.getBoundingClientRect().height); if(shH>0) r.setProperty('--saleHeadBottom', (tbH+shH)+'px'); }
  }
  function init(){
    var tra=document.getElementById('tab-tra'); if(!tra){ setTimeout(init,300); return; }
    var _wrap=document.querySelector('.wrap');
    if(_wrap && _wrap.parentElement && _wrap.children.length===1 && _wrap.firstElementChild.classList.contains('topbar')){ _wrap.parentElement.insertBefore(_wrap.firstElementChild,_wrap); _wrap.remove(); }
    if(!document.getElementById('tra-head')){
      var sq=tra.querySelector('#sq');
      var searchRow=sq?sq.closest('div'):tra.children[0];
      var filters=tra.querySelector('.filters-wrap');
      var head=document.createElement('div'); head.id='tra-head';
      tra.insertBefore(head, tra.firstChild);
      if(searchRow) head.appendChild(searchRow);
      if(filters) head.appendChild(filters);
    }
    var sale=document.getElementById('tab-sale');
    if(sale && !document.getElementById('sale-head')){
      var sHeaderBlock=sale.children[0];
      var scount=document.getElementById('scount');
      var sHead=document.createElement('div'); sHead.id='sale-head';
      sale.insertBefore(sHead, sale.firstChild);
      if(sHeaderBlock) sHead.appendChild(sHeaderBlock);
      if(scount) sHead.appendChild(scount);
      var saleRow=sHead.nextElementSibling;
      if(saleRow && saleRow.children[0]) saleRow.children[0].id='sale-size-sidebar';
    }
    if(typeof window.renderSale==='function' && !window.renderSale._sticky){
      var _rs=window.renderSale;
      window.renderSale=function(){ var r=_rs.apply(this,arguments); setTimeout(measure,60); return r; };
      window.renderSale._sticky=true;
    }
    measure();
    window.addEventListener('resize', measure);
    setTimeout(measure, 500);
  }
  if(document.readyState!=='loading') setTimeout(init,250);
  else document.addEventListener('DOMContentLoaded',function(){ setTimeout(init,250); });
})();


